@pragma('vm:entry-point')
bool isRightAlignedStaircase(List<String> rows) {
  int leading(String s) {
    int n = 0;
    while (n < s.length && s[n] == ' ') n++;
    return n;
  }
  if (rows.isEmpty) return true;
  int p = leading(rows[0]);
  if (p != 0) return false;
  for (int i = 1; i < rows.length; i++) {
    int c = leading(rows[i]);
    if (c != p + 1) return false;
    p = c;
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isRightAlignedStaircase([""," a","  b","   c"]) == true);
  assert(isRightAlignedStaircase([" a","  b"]) == false);
  assert(isRightAlignedStaircase([]) == true);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = isRightAlignedStaircase;

  expect(candidate([]), true);
  expect(candidate(["abc"]), true);
  expect(candidate([" abc"]), false);
  expect(candidate([""," x","  y","   z"]), true);
  expect(candidate(["", " ", "  ", "   ", "    "]), true);
  expect(candidate([" x","  y"]), false);
  expect(candidate(["","  a","   b"]), false);
  expect(candidate([""," a","b","  c"]), false);
  expect(candidate(["a"," b","  c"]), true);
}

