@pragma('vm:entry-point')
bool canStabilizeTelemetry(List<int> samples, int tolerance) {
  if (samples.length <= 1) {
    return true;
  }
  for (int i = 1; i < samples.length; i++) {
    List<int> left = samples.sublist(0, i);
    List<int> right = samples.sublist(i);
    int leftSum = left.fold(0, (a, b) => a + b);
    int rightSum = right.fold(0, (a, b) => a + b);
    if ((leftSum - rightSum).abs() <= tolerance) {
      if (canStabilizeTelemetry(left, tolerance) &&
          canStabilizeTelemetry(right, tolerance)) {
        return true;
      }
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(canStabilizeTelemetry([5, 5], 0) == true);
  assert(canStabilizeTelemetry([1, 2, 3], 2) == true);
  assert(canStabilizeTelemetry([1, 2, 3], 0) == false);
  print('All tests passed!');
