@pragma('vm:entry-point')
int maxPlaylistPopularity(List<int> durations, List<int> popularities, int maxDuration) {
  if (durations.isEmpty) return 0;
  int n = durations.length;
  List<int> prev2 = List<int>.filled(maxDuration + 1, 0);
  List<int> prev = List<int>.filled(maxDuration + 1, 0);
  for (int i = 0; i < n; i++) {
    int dur = durations[i];
    int pop = popularities[i];
    List<int> curr = List<int>.from(prev);
    if (dur <= maxDuration) {
      for (int d = dur; d <= maxDuration; d++) {
        int candidate = prev2[d - dur] + pop;
        if (candidate > curr[d]) {
          curr[d] = candidate;
        }
      }
    }
    prev2 = prev;
    prev = curr;
  }
  int best = 0;
  for (int v in prev) {
    if (v > best) best = v;
  }
  return best;
}

@pragma('vm:entry-point')
void main() {
  assert(maxPlaylistPopularity([30, 40, 20], [10, 20, 15], 60) == 25);
  assert(maxPlaylistPopularity([], [], 100) == 0);
  assert(maxPlaylistPopularity([45], [30], 50) == 30);
  print('All tests passed!');
}

