List<int> filledCellsPerWindow(String row, int width) {
  if (width <= 0 || width > row.length) return <int>[];
  var count = 0;
  for (var i = 0; i < width; i++) {
    if (row[i] == '#') count++;
  }
  final result = <int>[count];
  for (var i = width; i < row.length; i++) {
    if (row[i] == '#') count++;
    if (row[i - width] == '#') count--;
    result.add(count);
  }
  return result;
}

@pragma('vm:entry-point')
