@pragma('vm:entry-point')
Map<String, int> count5GhzSignalBins(List<int> signals) {
  final counts = {'excellent': 0, 'good': 0, 'fair': 0, 'poor': 0};
  final bins = ['excellent', 'good', 'fair', 'poor'];
  for (final signal in signals) {
    if ((signal & 4) != 0) {
      final bin = signal & 3;
      counts[bins[bin]] = counts[bins[bin]]! + 1;
    }
  }
  return counts;
}

