@pragma('vm:entry-point')
List<int> processShipmentUndoLog(List<String> operations) {
  List<int> stack = [];
  List<int> result = [];
  int currentWeight = 0;
  for (String op in operations) {
    if (op == 'UNDO') {
      if (stack.isNotEmpty) {
        currentWeight -= stack.removeLast();
      }
    } else {
      int weight = int.parse(op.substring(4));
      stack.add(weight);
      currentWeight += weight;
    }
    result.add(currentWeight);
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(processShipmentUndoLog(["ADD:10", "ADD:20", "UNDO", "ADD:5"]).toString() == "[10, 30, 10, 15]");
  assert(processShipmentUndoLog([]).toString() == "[]");
  assert(processShipmentUndoLog(["UNDO", "ADD:50", "UNDO", "UNDO"]).toString() == "[0, 50, 0, 0]");
  print('All tests passed!');
}

tests:
