  final candidate = processShipmentUndoLog;

  expect(candidate(["ADD:10", "ADD:20", "UNDO", "ADD:5"]), [10, 30, 10, 15]);
  expect(candidate([]), []);
  expect(candidate(["UNDO"]), [0]);
  expect(candidate(["ADD:100"]), [100]);
  expect(candidate(["UNDO", "ADD:50", "UNDO", "UNDO"]), [0, 50, 0, 0]);
  expect(candidate(["ADD:5", "ADD:5", "ADD:5", "UNDO", "UNDO", "UNDO", "UNDO"]), [5, 10, 15, 10, 5, 0, 0]);
  expect(candidate(["ADD:1", "UNDO", "ADD:2", "UNDO", "ADD:3"]), [1, 0, 2, 0, 3]);
}

