@pragma('vm:entry-point')
int countLongTracks(String playlist, int minSeconds) {
  if (playlist.isEmpty) return 0;
  int count = 0;
  for (String track in playlist.split(',')) {
    int firstColon = track.indexOf(':');
    if (firstColon == -1) continue;
    int secondColon = track.indexOf(':', firstColon + 1);
    if (secondColon == -1) continue;
    int minutes = int.parse(track.substring(firstColon + 1, secondColon));
    int seconds = int.parse(track.substring(secondColon + 1));
    if (minutes * 60 + seconds >= minSeconds) {
      count++;
    }
  }
  return count;
}

