@pragma('vm:entry-point')
List<int> longestThermostatIncreaseRun(List<int> schedule) {
  if (schedule.isEmpty) return [-1, 0];
  int bestStart = 0, bestLen = 1;
  int curStart = 0, curLen = 1;
  for (int i = 1; i < schedule.length; i++) {
    if (schedule[i] > schedule[i - 1]) {
      curLen++;
    } else {
      curStart = i;
      curLen = 1;
    }
    if (curLen > bestLen) {
      bestLen = curLen;
      bestStart = curStart;
    }
  }
  return [bestStart, bestLen];
}

