@pragma('vm:entry-point')
String processElectionResults(List<String> events) {
  List<String> voteStack = [];
  Map<String, int> tally = {};
  for (String event in events) {
    if (event.startsWith('VOTE ')) {
      String candidate = event.substring(5);
      voteStack.add(candidate);
      tally[candidate] = (tally[candidate] ?? 0) + 1;
    } else if (event == 'UNDO') {
      if (voteStack.isNotEmpty) {
        String last = voteStack.removeLast();
        int count = tally[last]!;
        if (count == 1) {
          tally.remove(last);
        } else {
          tally[last] = count - 1;
        }
      }
    }
  }
  if (tally.isEmpty) return '';
  List<String> candidates = tally.keys.toList()..sort();
  return candidates.map((c) => '$c: ${tally[c]}').join(', ');
}

@pragma('vm:entry-point')
void main() {
  assert(processElectionResults(['VOTE Alice', 'VOTE Bob', 'VOTE Alice']) == 'Alice: 2, Bob: 1');
  assert(processElectionResults(['VOTE Alice', 'UNDO', 'VOTE Bob']) == 'Bob: 1');
  assert(processElectionResults([]) == '');
  print('All tests passed!');
}

