bool isMorseBinaryPrime(String morse) {
  if (morse.isEmpty) return false;
  for (int i = 0; i < morse.length; i++) {
    if (morse[i] != '.' && morse[i] != '-') {
      return false;
    }
  }
  int value = 0;
  for (int i = 0; i < morse.length; i++) {
    value <<= 1;
    if (morse[i] == '-') {
      value |= 1;
    }
  }
  if (value <= 1) return false;
  if (value == 2) return true;
  if (value % 2 == 0) return false;
  for (int i = 3; i * i <= value; i += 2) {
    if (value % i == 0) {
      return false;
    }
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isMorseBinaryPrime("-.") == true);
  assert(isMorseBinaryPrime(".") == false);
  assert(isMorseBinaryPrime("...") == false);
  print('All tests passed!');
}

