  assert(binSignalReadings("-45,-72,-30,-88,-55") == "E:1,G:2,F:1,W:1");
  assert(binSignalReadings("") == "E:0,G:0,F:0,W:0");
  assert(binSignalReadings("-90") == "E:0,G:0,F:0,W:1");
  print('All tests passed!');
}

