@pragma('vm:entry-point')
String findShortestComplexPasswordSegment(String password) {
  int left = 0;
  int minLength = 999999;
  int bestStart = -1;
  int lower = 0, upper = 0, digit = 0, special = 0;

  for (int right = 0; right < password.length; right++) {
    int code = password.codeUnitAt(right);
    if (code >= 97 && code <= 122) {
      lower++;
    } else if (code >= 65 && code <= 90) {
      upper++;
    } else if (code >= 48 && code <= 57) {
      digit++;
    } else {
      special++;
    }

    while (lower > 0 && upper > 0 && digit > 0 && special > 0) {
      int len = right - left + 1;
      if (len < minLength) {
        minLength = len;
        bestStart = left;
      }
      int leftCode = password.codeUnitAt(left);
      if (leftCode >= 97 && leftCode <= 122) {
        lower--;
      } else if (leftCode >= 65 && leftCode <= 90) {
        upper--;
      } else if (leftCode >= 48 && leftCode <= 57) {
        digit--;
      } else {
        special--;
      }
      left++;
    }
  }

  if (bestStart == -1) return "INVALID";
  return password.substring(bestStart, bestStart + minLength);
}

@pragma('vm:entry-point')
void main() {
  assert(findShortestComplexPasswordSegment('aA1!') == 'aA1!');
  assert(findShortestComplexPasswordSegment('') == 'INVALID');
  print('All tests passed!');
}

