  expect(findShortestComplexPasswordSegment(''), 'INVALID');
  expect(findShortestComplexPasswordSegment('aA1!!'), 'aA1!');
  expect(findShortestComplexPasswordSegment('xyzA1!B2@'), 'zA1!');
  expect(findShortestComplexPasswordSegment('1!aB c'), '1!aB');
}

