@pragma('vm:entry-point')
String orderTrafficPhases(List<String> phases) {
  if (phases.isEmpty) return '';
  List<String> sorted = List<String>.from(phases);
  sorted.sort((a, b) {
    List<int> parsePhase(String s) {
      List<String> parts = s.split('-');
      int r = int.parse(parts[0].substring(1));
      int y = int.parse(parts[1].substring(1));
      int g = int.parse(parts[2].substring(1));
      return [r, y, g];
    }
    List<int> pa = parsePhase(a);
    List<int> pb = parsePhase(b);
    int totalA = pa[0] + pa[1] + pa[2];
    int totalB = pb[0] + pb[1] + pb[2];
    int crossA = pa[2] * totalB;
    int crossB = pb[2] * totalA;
    if (crossA != crossB) {
      return crossB.compareTo(crossA);
    }
    if (totalA != totalB) {
      return totalA.compareTo(totalB);
    }
    return a.compareTo(b);
  });
  return sorted.join(', ');
}

@pragma('vm:entry-point')
void main() {
  assert(orderTrafficPhases([]) == '');
  assert(orderTrafficPhases(['R10-Y5-G30']) == 'R10-Y5-G30');
  assert(orderTrafficPhases(['R5-Y2-G3', 'R5-Y2-G10']) == 'R5-Y2-G10, R5-Y2-G3');
