int findQuietZoneStart(List<int> modules) {
  int left = 0;
  int right = modules.length;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (modules[mid] == 1) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return left;
}

