@pragma('vm:entry-point')
int countVipSections(List<int> seating, int threshold) {
  List<int> solve(int i) {
    if (i >= seating.length || seating[i] == -1) return [0, 0];
    int l = 2 * i + 1, r = 2 * i + 2;
    bool hasL = l < seating.length && seating[l] != -1;
    bool hasR = r < seating.length && seating[r] != -1;
    if (!hasL && !hasR) {
      bool vip = seating[i] >= threshold;
      return [vip ? 1 : 0, vip ? 1 : 0];
    }
    List<int> left = solve(l);
    List<int> right = solve(r);
    bool vip = left[0] == 1 && right[0] == 1;
    int count = left[1] + right[1] + (vip ? 1 : 0);
    return [vip ? 1 : 0, count];
  }
  return solve(0)[1];
}

@pragma('vm:entry-point')
void main() {
  assert(countVipSections([5], 3) == 1);
  assert(countVipSections([0, 5, 3], 3) == 3);
