int bracketMeetingRound(int playerA, int playerB) {
  if (playerA == playerB || playerA < 0 || playerB < 0) {
    return 0;
  }
  int xorVal = playerA ^ playerB;
  int round = 0;
  while (xorVal > 0) {
    round++;
    xorVal >>= 1;
  }
  return round;
}

