@pragma('vm:entry-point')
String findBestMemberPurchase(List<int> sortedPricesCents, int budgetCents) {
  int applyDiscountAndRound(int price) {
    int discounted = (price * 95) ~/ 100;
    int rem = discounted % 5;
    return rem <= 2 ? discounted - rem : discounted + (5 - rem);
  }

  int lo = 0, hi = sortedPricesCents.length - 1;
  int bestIdx = -1;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (applyDiscountAndRound(sortedPricesCents[mid]) <= budgetCents) {
      bestIdx = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }

  if (bestIdx == -1) return "NONE";
  int p = applyDiscountAndRound(sortedPricesCents[bestIdx]);
  int dollars = p ~/ 100;
  int cents = p % 100;
  return "\$${dollars}.${cents.toString().padLeft(2, '0')}";
}

@pragma('vm:entry-point')
void main() {
  assert(findBestMemberPurchase([100, 199, 250, 303, 499], 300) == "\$2.85");
  assert(findBestMemberPurchase([], 500) == "NONE");
  assert(findBestMemberPurchase([105], 100) == "\$1.00");
  print('All tests passed!');
}

tests:
