int countComparatorSwapsForCorrections(String original, List<String> candidates) {
  int dist(String a, String b) {
    int d = (a.length - b.length).abs();
    int m = a.length < b.length ? a.length : b.length;
    for (int i = 0; i < m; i++) {
      if (a[i] != b[i]) d++;
    }
    return d;
  }
  List<String> lst = List<String>.from(candidates);
  int swaps = 0;
  for (int i = 0; i < lst.length; i++) {
    for (int j = 0; j < lst.length - 1 - i; j++) {
      int d1 = dist(original, lst[j]);
      int d2 = dist(original, lst[j + 1]);
      bool shouldSwap = false;
      if (d1 > d2) {
        shouldSwap = true;
      } else if (d1 == d2 && lst[j].length > lst[j + 1].length) {
        shouldSwap = true;
      } else if (d1 == d2 && lst[j].length == lst[j + 1].length && lst[j].compareTo(lst[j + 1]) > 0) {
        shouldSwap = true;
      }
      if (shouldSwap) {
        String tmp = lst[j];
        lst[j] = lst[j + 1];
        lst[j + 1] = tmp;
        swaps++;
      }
    }
  }
  return swaps;
}

