bool hasValidRoundedCents(String amounts) {
  if (amounts.isEmpty) return false;
  int state = 0;
  for (int i = 0; i < amounts.length; i++) {
    String c = amounts[i];
    if (state == 0 && c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) state = 1;
    else if (state == 1 && c == '.') state = 2;
    else if (state == 1 && c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {}
    else if (state == 2 && c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) state = 3;
    else if (state == 3 && (c == '0' || c == '5')) state = 4;
    else if (state == 4 && c == ',') state = 0;
    else return false;
  }
  return state == 4;
}

