bool binarySearchMazeCell(List<List<int>> maze, int target) {
  if (maze.isEmpty || maze[0].isEmpty) return false;
  int rows = maze.length;
  int cols = maze[0].length;
  int left = 0;
  int right = rows * cols - 1;
  while (left <= right) {
    int mid = left + ((right - left) ~/ 2);
    int row = mid ~/ cols;
    int col = mid % cols;
    if (maze[row][col] == target) return true;
    if (maze[row][col] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(binarySearchMazeCell([[1,2],[3,4]], 3) == true);
  assert(binarySearchMazeCell([[]], 1) == false);
  assert(binarySearchMazeCell([[5]], 5) == true);
  print('All tests passed!');
}

