@pragma('vm:entry-point')
int computeMaxItemsByDensity(List<Map<String, int>> items, int maxWeight, int maxVolume) {
  var sortedItems = List<Map<String, int>>.from(items);
  sortedItems.sort((a, b) {
    int w1 = a['weight']!;
    int v1 = a['volume']!;
    int w2 = b['weight']!;
    int v2 = b['volume']!;
    int cmp = (w1 * v2).compareTo(w2 * v1);
    if (cmp != 0) return cmp;
    cmp = w2.compareTo(w1);
    if (cmp != 0) return cmp;
    return v1.compareTo(v2);
  });
  int currentWeight = 0;
  int currentVolume = 0;
  int count = 0;
  for (var item in sortedItems) {
    int w = item['weight']!;
    int v = item['volume']!;
    if (currentWeight + w <= maxWeight && currentVolume + v <= maxVolume) {
      currentWeight += w;
      currentVolume += v;
      count++;
    } else {
      break;
    }
  }
  return count;
}

