bool isInSatellitePassWindow(int day, int firstPassDay, int period, int duration) {
  if (period <= 0 || duration <= 0) return false;
  if (duration > period) return false;
  if (day < firstPassDay) return false;
  int daysSinceFirst = day - firstPassDay;
  int cyclePosition = daysSinceFirst % period;
  return cyclePosition < duration;
}

