@pragma('vm:entry-point')
List<int> dnaColumnTransitions(List<String> dnaGrid) {
  if (dnaGrid.isEmpty || dnaGrid[0].isEmpty) {
    return [];
  }

  bool isPurine(String base) => base == 'A' || base == 'G';

  int cols = dnaGrid[0].length;
  List<int> result = List.filled(cols, 0);

  for (int j = 0; j < cols; j++) {
    for (int i = 0; i < dnaGrid.length - 1; i++) {
      String current = dnaGrid[i][j];
      String next = dnaGrid[i + 1][j];
      if (isPurine(current) != isPurine(next)) {
        result[j]++;
      }
    }
  }

  return result;
}

