List<int> parseHexPixels(String hexPixels) {
  List<int> result = [];
  if (hexPixels.isEmpty) return result;
  List<String> tokens = hexPixels.trim().split(RegExp(r'\s+'));
  for (String token in tokens) {
    if (token.length != 6) continue;
    int r = int.parse(token.substring(0, 2), radix: 16);
    int g = int.parse(token.substring(2, 4), radix: 16);
    int b = int.parse(token.substring(4, 6), radix: 16);
    result.add(r);
    result.add(g);
    result.add(b);
  }
  return result;
}

@pragma('vm:entry-point')
