List<String> compressPacketPayload(String payload) {
  if (payload.isEmpty) return [];
  List<String> encoded = [];
  int count = 1;
  for (int i = 1; i < payload.length; i++) {
    if (payload[i] == payload[i - 1]) {
      count++;
    } else {
      encoded.add('${payload[i - 1]}$count');
      count = 1;
    }
  }
  encoded.add('${payload[payload.length - 1]}$count');
  return encoded;
}

