bool packetCollidesWithAny(int px, int py, int pw, int ph, List<List<int>> existingPackets) {
  if (pw <= 0 || ph <= 0) return false;
  for (var packet in existingPackets) {
    int ex = packet[0], ey = packet[1], ew = packet[2], eh = packet[3];
    if (ew <= 0 || eh <= 0) continue;
    bool xOverlap = px < ex + ew && ex < px + pw;
    bool yOverlap = py < ey + eh && ey < py + ph;
