List<int> sortDrySpotsByProximity(List<List<int>> moistureGrid, int refRow, int refCol, int threshold) {
  List<List<int>> drySpots = [];
  for (int r = 0; r < moistureGrid.length; r++) {
    for (int c = 0; c < moistureGrid[r].length; c++) {
      int moisture = moistureGrid[r][c];
      if (moisture < threshold) {
        int dist = (r - refRow).abs() + (c - refCol).abs();
        drySpots.add([dist, moisture, r, c]);
      }
    }
  }
  drySpots.sort((a, b) {
    for (int i = 0; i < 4; i++) {
      int cmp = a[i].compareTo(b[i]);
      if (cmp != 0) return cmp;
    }
    return 0;
  });
  return drySpots.map((spot) => spot[1]).toList();
}

