@pragma('vm:entry-point')
int countDisjointPatternBarcodePairs(List<String> barcodes) {
  Map<String, Map<int, int>> groupedMasks = {};
  int pairs = 0;

  for (String code in barcodes) {
    if (code.isEmpty) {
      continue;
    }

    Map<String, int> freq = {};
    int mask = 0;
    bool valid = true;

    for (int i = 0; i < code.length; i++) {
      String ch = code[i];
      int digit = ch.codeUnitAt(0) - 48;

      if (digit < 0 || digit > 9) {
        valid = false;
        break;
      }

      freq[ch] = (freq[ch] ?? 0) + 1;
      mask |= (1 << digit);
    }

    if (!valid) {
      continue;
    }

    List<int> counts = freq.values.toList();
    counts.sort();

    String signature = '${code.length}|';
    for (int count in counts) {
      signature += '$count,';
    }

    Map<int, int> existing = groupedMasks.putIfAbsent(signature, () => {});

    existing.forEach((otherMask, seenCount) {
      if ((otherMask & mask) == 0) {
        pairs += seenCount;
      }
    });

    existing[mask] = (existing[mask] ?? 0) + 1;
  }

  return pairs;
}

@pragma('vm:entry-point')
void main() {
  assert(countDisjointPatternBarcodePairs(["0011", "2233", "0123"]) == 1);
  assert(countDisjointPatternBarcodePairs(["1212", "3434", "5656"]) == 3);
  assert(countDisjointPatternBarcodePairs(["999", "888", "989"]) == 1);
  print('All tests passed!');
}

