List<int> sortManifestWeights(List<int> weights, int priorityLimit) {
  List<int> result = List<int>.from(weights);
  result.sort((a, b) {
    bool aPriority = a >= priorityLimit;
    bool bPriority = b >= priorityLimit;

    if (aPriority && !bPriority) return -1;
