String analyzeSoilMoistureGrid(List<List<double>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 'Empty grid';
  Map<String, int> freq = {'Dry': 0, 'Moist': 0, 'Wet': 0};
  Set<double> seenLevels = {};
  for (int r = 0; r < grid.length; r++) {
    for (int c = 0; c < grid[r].length; c++) {
      double m = grid[r][c];
      seenLevels.add(m);
      if (m <= 0.25) {
        freq['Dry'] = freq['Dry']! + 1;
      } else if (m <= 0.5) {
        freq['Moist'] = freq['Moist']! + 1;
      } else {
        freq['Wet'] = freq['Wet']! + 1;
      }
    }
  }
  String groups = 'Levels:${seenLevels.length}';
  return 'Dry:${freq['Dry']} Moist:${freq['Moist']} Wet:${freq['Wet']} $groups';
}

