bool isNetworkReliable(List<int> readings) {
  if (readings.isEmpty) return false;

  for (int r in readings) {
    if (r < -85) return false;
  }

  List<int> segmentLengths = [];
  int currentLength = 0;

  for (int r in readings) {
    if (r >= -70) {
      currentLength++;
    } else {
      if (currentLength > 0) {
        segmentLengths.add(currentLength);
        currentLength = 0;
      }
    }
  }
  if (currentLength > 0) {
    segmentLengths.add(currentLength);
  }

  if (segmentLengths.length < 2) return false;

  int longest = 0;
  for (int len in segmentLengths) {
    if (len > longest) longest = len;
  }

  return longest >= 3;
}

