  expect(longestValidPasswordSegment(' ', 0), 0);
  expect(longestValidPasswordSegment('', 0), 0);
  expect(longestValidPasswordSegment('A1!@#B2', 2), 4);
  expect(longestValidPasswordSegment('!@#', 2), 0);
  expect(longestValidPasswordSegment('aA1! B2@', 1), 4);
  expect(longestValidPasswordSegment('A1!@B2#C3', 2), 6);
  expect(longestValidPasswordSegment('1aB!@#', 1), 4);
}

