@pragma('vm:entry-point')
String longestStableErrorPeriod(List<int> dailyErrors) {
  if (dailyErrors.isEmpty) return "no period";
  int n = dailyErrors.length;
  List<int> dp = List<int>.filled(n, 1);
  int maxLen = 1;
  int endIdx = 0;
  for (int i = 1; i < n; i++) {
    if (dailyErrors[i] >= dailyErrors[i - 1]) {
      dp[i] = dp[i - 1] + 1;
      if (dp[i] > maxLen) {
        maxLen = dp[i];
        endIdx = i;
      }
    }
  }
  int start = endIdx - maxLen + 1;
  return "$start-$endIdx:$maxLen";
}

@pragma('vm:entry-point')
void main() {
  assert(longestStableErrorPeriod([1,3,2,4,5,4]) == "2-4:3");
  assert(longestStableErrorPeriod([]) == "no period");
  assert(longestStableErrorPeriod([5]) == "0-0:1");
  print('All tests passed!');
}

