@pragma('vm:entry-point')
int countAcceptableWifiSignals(List<int> signals, int left, int right) {
  if (left > right) return 0;
  if (left == right) return signals[left] >= -67 ? 1 : 0;
  int mid = (left + right) ~/ 2;
  int leftCount = countAcceptableWifiSignals(signals, left, mid);
  int rightCount = countAcceptableWifiSignals(signals, mid + 1, right);
  return leftCount + rightCount;
}

@pragma('vm:entry-point')
void main() {
  assert(countAcceptableWifiSignals([-40, -75, -60], 0, 2) == 2);
  assert(countAcceptableWifiSignals([-70, -80], 0, 1) == 0);
  assert(countAcceptableWifiSignals([-67], 0, 0) == 1);
  print('All tests passed!');
