@pragma('vm:entry-point')
List<int> foldDNA(String dna) {
  if (dna.length < 2) return [0, 0];
  String first = dna[0];
  String last = dna[dna.length - 1];
  bool isAT = (first == 'A' && last == 'T') || (first == 'T' && last == 'A');
  bool isCG = (first == 'C' && last == 'G') || (first == 'G' && last == 'C');
  if (isAT || isCG) {
    List<int> inner = foldDNA(dna.substring(1, dna.length - 1));
    if (isAT) {
      return [inner[0] + 1, inner[1]];
    } else {
      return [inner[0], inner[1] + 1];
    }
  } else {
    return [0, 0];
  }
}

