bool areLogLinesSortedBySeverity(List<String> logLines) {
  Map<String, int> severityOrder = {'INFO': 0, 'WARN': 1, 'ERROR': 2};
  for (int i = 1; i < logLines.length; i++) {
    String prevTag = logLines[i - 1].split(':')[0];
    String currTag = logLines[i].split(':')[0];
