@pragma('vm:entry-point')
int cardsDueInRange(List<int> nextDueDays, List<int> intervals, int startDay, int endDay) {
  if (startDay > endDay || nextDueDays.length != intervals.length) {
    return 0;
  }
  int total = 0;
  for (int i = 0; i < nextDueDays.length; i++) {
    int nextDue = nextDueDays[i];
    int interval = intervals[i];
    if (interval <= 0 || nextDue > endDay) {
      continue;
    }
    int diff = startDay - nextDue;
    int firstDue;
    if (diff <= 0) {
      firstDue = nextDue;
    } else {
      int k = (diff + interval - 1) ~/ interval;
      firstDue = nextDue + k * interval;
    }
    if (firstDue > endDay) {
      continue;
    }
    total += (endDay - firstDue) ~/ interval + 1;
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(cardsDueInRange([0, 1, 5], [3, 2, 5], 0, 10) == 11);
  assert(cardsDueInRange([], [], 0, 5) == 0);
