@pragma('vm:entry-point')
List<int> findTransactionSequence(List<int> ledger, int k, int target) {
  final n = ledger.length;
  if (n < k) return [];
  int windowSum = 0;
  for (int i = 0; i < k; i++) {
    windowSum += ledger[i];
  }
  if (windowSum == target) return [0, k - 1];
  for (int i = 1; i <= n - k; i++) {
    windowSum = windowSum - ledger[i - 1] + ledger[i + k - 1];
    if (windowSum == target) {
      return [i, i + k - 1];
    }
  }
  return [];
}

@pragma('vm:entry-point')
