@pragma('vm:entry-point')
bool canSegmentMorseCode(List<String> symbols) {
  int n = symbols.length;
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true;
  Set<String> valid = {'.', '-', '..', '.-', '-.', '--'};
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j]) {
        String sub = symbols.sublist(j, i).join('');
        if (valid.contains(sub)) {
          dp[i] = true;
          break;
        }
      }
    }
  }
  return dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(canSegmentMorseCode([]) == true);
