@pragma('vm:entry-point')
List<int> decodeCashRoundedTotals(String encoded) {
  if (encoded.isEmpty) return [];
  List<int> results = [];
  List<String> items = encoded.split('|');
  for (String item in items) {
    int discount = 0;
    String mainPart = item;
    if (item.contains('*')) {
      List<String> discParts = item.split('*');
      mainPart = discParts[0];
      discount = int.parse(discParts[1]);
    }
    List<String> parts = mainPart.split('x');
    int quantity = int.parse(parts[0]);
    int priceCents = int.parse(parts[1]);
    int total = quantity * priceCents;
    if (discount > 0) {
      total = total - (total * discount ~/ 100);
    }
    int rounded = ((total + 2) ~/ 5) * 5;
    results.add(rounded);
  }
  return results;
}

@pragma('vm:entry-point')
void main() {
  assert(decodeCashRoundedTotals("3x100").toString() == "[300]");
  assert(decodeCashRoundedTotals("1x99").toString() == "[100]");
