List<String> findRunLengthCorrections(String word) {
  List<String> corrections = [];
  int i = 0;
  while (i < word.length) {
    int j = i;
    while (j < word.length && word[j] == word[i]) {
      j++;
    }
    int runLength = j - i;
    if (runLength >= 3) {
      String prefix = word.substring(0, i);
      String suffix = word.substring(j);
      corrections.add(prefix + word[i] + suffix);
      corrections.add(prefix + word[i] + word[i] + suffix);
    }
    i = j;
  }
  return corrections;
}

