@pragma('vm:entry-point')
int calculateValidManifestGcd(List<int> containerWeights) {
  List<int> validWeights = [];
  for (int weight in containerWeights) {
    if (weight <= 0) continue;
    int sum = 0;
    int temp = weight;
    while (temp > 0) {
      sum += temp % 8;
      temp ~/= 8;
    }
    if (_isPrime(sum)) {
      validWeights.add(weight);
    }
  }
  if (validWeights.isEmpty) return 0;
  int result = validWeights[0];
  for (int i = 1; i < validWeights.length; i++) {
    result = _gcd(result, validWeights[i]);
  }
  return result;
}

bool _isPrime(int n) {
  if (n <= 1) return false;
  if (n == 2 || n == 3) return true;
  if (n % 2 == 0 || n % 3 == 0) return false;
  for (int i = 5; i * i <= n; i += 6) {
    if (n % i == 0 || n % (i + 2) == 0) return false;
  }
  return true;
}

int _gcd(int a, int b) {
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateValidManifestGcd([12, 102]) == 6);
  assert(calculateValidManifestGcd([15, 31]) == 0);
