bool isShipmentScheduleValid(int startDay, List<int> durations, Set<int> holidays, int maxTotalDays) {
  if (durations.isEmpty) return false;
  if (startDay % 7 >= 5) return false; // Saturday or Sunday start
  int totalDays = 0;
  for (int d in durations) {
    if (d <= 0) return false;
    totalDays += d;
  }
  if (totalDays > maxTotalDays) return false;
  int currentDay = startDay;
  for (int d in durations) {
    currentDay += d;
    int dow = currentDay % 7;
    if (dow >= 5) return false; // arrival on weekend
    if (holidays.contains(currentDay)) return false;
  }
  return true;
}

