bool hasCraftableWindow(List<int> itemPowers, int windowSize, int threshold) {
  // A crafting recipe needs `windowSize` consecutive inventory slots whose
  // combined item power is at least `threshold`.
  if (windowSize <= 0 || windowSize > itemPowers.length) return false;
  int sum = 0;
  for (int i = 0; i < windowSize; i++) {
    sum += itemPowers[i];
  }
  if (sum >= threshold) return true;
  for (int i = windowSize; i < itemPowers.length; i++) {
    sum += itemPowers[i] - itemPowers[i - windowSize];
    if (sum >= threshold) return true;
  }
  return false;
}

