double scanQrModuleTransitionDensity(List<int> modules) {
  if (modules.length < 2) return 0.0;
  int transitions = 0;
  int prev = modules[0];
  for (int i = 1; i < modules.length; i++) {
    if (modules[i] != prev) {
      transitions++;
      prev = modules[i];
    }
  }
  return transitions / (modules.length - 1.0);
}

