List<String> expandWildcardStrand(String strand) {
  if (strand.isEmpty) return [''];
  final List<String> tails = expandWildcardStrand(strand.substring(1));
  final String first = strand[0];
  final List<String> bases = first == 'N' ? ['A', 'C', 'G', 'T'] : [first];
  final List<String> result = <String>[];
  for (final b in bases) {
    for (final t in tails) {
      result.add(b + t);
    }
  }
  return result;
}

