List<String> decodeTideReadings(List<int> readings) {
  List<String> results = [];
  for (int r in readings) {
    if ((r & 4) == 0) continue;
    int height = (r >> 3) & 31;
    bool rising = (r & 1) == 1;
    bool extreme = (r & 2) == 2;
    double h = height * 0.5;
    String dir = rising ? 'rising' : 'falling';
    String ext = extreme ? ' [extreme]' : '';
    results.add('${h.toStringAsFixed(1)}m $dir$ext');
  }
  return results;
}

