@pragma('vm:entry-point')
String findFirstMissingShelfCode(List<String> codes, String prefix, int startNum) {
  if (codes.isEmpty) {
    return '${prefix}-${startNum.toString().padLeft(3, '0')}';
  }
  int low = 0;
  int high = codes.length - 1;
  int result = codes.length;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    String code = codes[mid];
    int actualNum = int.parse(code.substring(code.indexOf('-') + 1));
    int expectedNum = startNum + mid;
    if (actualNum > expectedNum) {
      result = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  int missingNum = startNum + result;
  return '${prefix}-${missingNum.toString().padLeft(3, '0')}';
}

