int countMorseSymbolChains(String signal, List<String> symbols) {
  int search(int index) {
    if (index == signal.length) {
      return 1;
    }
    int total = 0;
    for (final symbol in symbols) {
      if (symbol.isEmpty) continue;
      if (index + symbol.length <= signal.length &&
          signal.substring(index, index + symbol.length) == symbol) {
        total += search(index + symbol.length);
      }
    }
    return total;
  }

  return search(0);
}

