List<int> sameColorSquares(int n, int r, int c) {
  if (n <= 0) return [];
  final targetParity = (r + c) % 2;
  final result = <int>[];
  for (int i = 0; i < n * n; i++) {
    final row = i ~/ n;
    final col = i % n;
    if ((row + col) % 2 == targetParity) {
      result.add(i);
    }
  }
  return result;
}

