bool hasValidThreeCharSegments(String password) {
  int n = password.length;
  if (n == 0 || n % 3 != 0) return false;
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true;
  for (int i = 3; i <= n; i += 3) {
    bool hasDigit = false;
    for (int j = i - 3; j < i; j++) {
      int c = password.codeUnitAt(j);
      if (c >= 48 && c <= 57) {
        hasDigit = true;
        break;
      }
    }
    dp[i] = dp[i - 3] && hasDigit;
  }
  return dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(hasValidThreeCharSegments("a1b") == true);
  assert(hasValidThreeCharSegments("abc") == false);
