@pragma('vm:entry-point')
String sortDnaStrandsByFitness(List<String> strands) {
  if (strands.isEmpty) return '';
  List<String> sorted = List<String>.from(strands);
  sorted.sort((a, b) {
    int gcA = 0, gcB = 0;
    for (int i = 0; i < a.length; i++) {
      if (a[i] == 'G' || a[i] == 'C') gcA++;
    }
    for (int i = 0; i < b.length; i++) {
      if (b[i] == 'G' || b[i] == 'C') gcB++;
    }
    if (gcA != gcB) return gcB.compareTo(gcA);
    if (a.length != b.length) return b.length.compareTo(a.length);
    bool palA = _isDnaPalindrome(a);
    bool palB = _isDnaPalindrome(b);
    if (palA != palB) return palA ? -1 : 1;
    return a.compareTo(b);
  });
  return sorted.join('|');
}

bool _isDnaPalindrome(String s) {
  int n = s.length;
  for (int i = 0; i < n ~/ 2; i++) {
    if (s[i] != s[n - 1 - i]) return false;
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(sortDnaStrandsByFitness([]) == '');
  assert(sortDnaStrandsByFitness(['GC']) == 'GC');
