@pragma('vm:entry-point')
String encodeBatteryCycles(String cycles) {
  if (cycles.isEmpty) return '';
  String rle = '';
  List<int> counts = [];
  int i = 0;
  while (i < cycles.length) {
    String ch = cycles[i];
    int count = 0;
    while (i < cycles.length && cycles[i] == ch) {
      count++;
      i++;
    }
    counts.add(count);
    int remaining = count;
    while (remaining > 0) {
      int chunk = remaining > 9 ? 9 : remaining;
      rle += '$ch$chunk';
      remaining -= chunk;
    }
  }
  int xorVal = 0;
  for (int c in counts) {
    xorVal ^= c;
  }
  return rle + xorVal.toRadixString(16).toUpperCase();
}

@pragma('vm:entry-point')
void main() {
  assert(encodeBatteryCycles('FFFFF') == 'F55');
  assert(encodeBatteryCycles('FFHHHLLLD') == 'F2H3L3D13');
