bool isValidAsciiArtBar(String row) {
  int state = 0;
  for (int i = 0; i < row.length; i++) {
    String c = row[i];
    if (state == 0) { if (c == '.') continue; if (c == '[') { state = 1; continue; } return false; }
    if (state == 1) { if (c == '=') { state = 2; continue; } return false; }
    if (state == 2) { if (c == '=') continue; if (c == ']') { state = 3; continue; } return false; }
    if (state == 3 && c != '.') return false;
  }
  return state == 3;
}

