@pragma('vm:entry-point')
bool coversDayWithinGap(List<int> departures, int maxGap) {
  // departures are minutes since midnight (valid range 0..1439).
  // Returns true if, after dropping invalid entries and duplicates,
  // no gap between consecutive trains (including the wrap-around past
  // midnight) exceeds maxGap minutes.
  if (maxGap <= 0) return false;
  final valid = <int>{};
  for (final m in departures) {
    if (m >= 0 && m < 1440) {
      valid.add(m);
    }
  }
  if (valid.isEmpty) return false;
  final sorted = valid.toList()..sort();
  for (var i = 1; i < sorted.length; i++) {
    if (sorted[i] - sorted[i - 1] > maxGap) {
      return false;
    }
  }
  final wrapGap = sorted.first + 1440 - sorted.last;
  return wrapGap <= maxGap;
}

@pragma('vm:entry-point')
