  assert(coversDayWithinGap([0, 360, 720, 1080], 360) == true);
  assert(coversDayWithinGap([0, 360, 720, 1080], 359) == false);
  assert(coversDayWithinGap([720], 1440) == true);
  print('All tests passed!');
}

