@pragma('vm:entry-point')
List<int> decodeBarcodeNibbles(List<int> rawBytes, int mask) {
  List<int> result = [];
  int m = mask & 0xF;
  for (int b in rawBytes) {
    int nibble = b & 0xF;
    int corrected = nibble ^ m;
    int count = 0;
    int temp = corrected;
    while (temp > 0) {
      count += temp & 1;
      temp >>= 1;
    }
    result.add(count);
  }
  return result;
}

