@pragma('vm:entry-point')
int calculateScheduleDisruption(List<int> temperatures, int idealTemp) {
  if (temperatures.isEmpty) return 0;
  List<int> indices = List<int>.generate(temperatures.length, (i) => i);
  indices.sort((a, b) {
    int diffA = (temperatures[a] - idealTemp).abs();
    int diffB = (temperatures[b] - idealTemp).abs();
    if (diffA != diffB) return diffA.compareTo(diffB);
    if (temperatures[a] != temperatures[b]) {
      return temperatures[a].compareTo(temperatures[b]);
    }
    return a.compareTo(b);
  });
  int disruptionCount = 0;
  for (int i = 0; i < indices.length; i++) {
    if (indices[i] != i) disruptionCount++;
  }
  return disruptionCount;
}

