@pragma('vm:entry-point')
List<int> extractErrorDepthsFromTrace(String trace) {
  List<int> depths = [];
  _parseTrace(trace, 0, 1, depths);
  return depths;
}

int _parseTrace(String trace, int index, int depth, List<int> depths) {
  while (index < trace.length) {
    if (trace[index] == '(') {
      index = _parseTrace(trace, index + 1, depth + 1, depths);
    } else if (trace[index] == ')') {
      return index + 1;
    } else if (trace[index] == 'E') {
      depths.add(depth);
      index++;
    } else {
      index++;
    }
  }
  return index;
}

@pragma('vm:entry-point')
void main() {
  assert(extractErrorDepthsFromTrace('I(E)W').toString() == '[2]');
  assert(extractErrorDepthsFromTrace('(E(E))').toString() == '[2, 3]');
  assert(extractErrorDepthsFromTrace('III').isEmpty);
  print('All tests passed!');
}

tests:
