  expect(extractErrorDepthsFromTrace(''), []);
  expect(extractErrorDepthsFromTrace('E'), [1]);
  expect(extractErrorDepthsFromTrace('((E))'), [3]);
  expect(extractErrorDepthsFromTrace('E(E)E'), [1, 2, 1]);
  expect(extractErrorDepthsFromTrace('W(I(E))D(E)'), [3, 2]);
}

