bool requiresElectionAudit(int votesA, int votesB) {
  int totalVotes = votesA + votesB;
  if (totalVotes <= 100) return false;

  int margin = votesA > votesB ? votesA - votesB : votesB - votesA;
  if (margin < 2) return false;
  if (margin == 2) return true;
  if (margin % 2 == 0) return false;

  for (int i = 3; i * i <= margin; i += 2) {
    if (margin % i == 0) return false;
  }
  return true;
}

