bool canSafelyUseItems(int current, String sequence, int capacity) {
  int count = current;
  for (int i = 0; i < sequence.length; i++) {
    final op = sequence[i];
    if (op == 'P') {
      count++;
    } else if (op == 'U' || op == 'D') {
      count--;
