List<int> reconcileFlaggedEntries(List<int> entries) {
  List<int> result = [];
  for (int entry in entries) {
    bool debit = (entry & 0x01) != 0;
    bool credit = (entry & 0x02) != 0;
    bool verified = (entry & 0x04) != 0;
    bool frozen = (entry & 0x08) != 0;
    int amount = (entry >> 16) & 0xFFFF;
    bool valid = debit ^ credit;
    if (!valid) continue;
    if (verified && !frozen) {
      result.add(amount);
    } else if (frozen) {
      result.add(-amount);
    }
  }
  return result;
}

