@pragma('vm:entry-point')
String sortPasswordRules(List<String> rules) {
  if (rules.isEmpty) return '';
  const priority = {'length': 0, 'uppercase': 1, 'digit': 2, 'special': 3};
  final sorted = List<String>.from(rules);
  sorted.sort((a, b) {
    final partsA = a.split(':');
    final partsB = b.split(':');
    if (partsA.length != 2 || partsB.length != 2) return 0;
    final typeA = partsA[0];
    final typeB = partsB[0];
    final valA = int.tryParse(partsA[1]) ?? 0;
    final valB = int.tryParse(partsB[1]) ?? 0;
    final prioA = priority[typeA] ?? 99;
    final prioB = priority[typeB] ?? 99;
    if (prioA != prioB) return prioA.compareTo(prioB);
    if (typeA == 'length') {
      return valA.compareTo(valB);
    } else {
      return valB.compareTo(valA);
    }
  });
  return sorted.join(',');
}

@pragma('vm:entry-point')
void main() {
  assert(sortPasswordRules([]) == '');
  assert(sortPasswordRules(['length:8']) == 'length:8');
  assert(sortPasswordRules(['uppercase:2', 'length:8', 'digit:1']) == 'length:8,uppercase:2,digit:1');
  print('All tests passed!');
}

