  expect(candidate(['uppercase:2', 'length:8', 'digit:1']), 'length:8,uppercase:2,digit:1');
  expect(candidate(['special:3', 'special:1']), 'special:3,special:1');
  expect(candidate(['unknown:5', 'length:8']), 'length:8,unknown:5');
  expect(candidate(['digit:2', 'uppercase:1', 'length:12', 'special:4']), 'length:12,uppercase:1,digit:2,special:4');
  expect(candidate(['length:5', 'length:5']), 'length:5,length:5');
  expect(candidate(['uppercase:3', 'digit:3', 'special:3']), 'uppercase:3,digit:3,special:3');
}

