List<String> batteryCycleStates(String log) {
  List<String> states = [];
  int charge = 0;

  for (int i = 0; i < log.length; i++) {
    String ch = log[i];
    if (ch == '+') {
      charge++;
    } else if (ch == '-' && charge > 0) {
      charge--;
    } else if (ch == '|') {
      if (charge == 0) {
        states.add('empty');
      } else if (charge >= 3) {
        states.add('full');
      } else {
        states.add('partial');
      }
      charge = 0;
    }
  }

  return states;
}

