bool areAsciiRowsTileCompatible(int rowLengthA, int rowLengthB) {
  if (rowLengthA <= 1 || rowLengthB <= 1) return false;
  int a = rowLengthA;
  int b = rowLengthB;
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
  }
  return a > 1;
}

