List<int> genrePlayCounts(List<List<int>> dailyPlaylists) {
  if (dailyPlaylists.isEmpty) return [];
  int cols = dailyPlaylists[0].length;
  List<int> totals = List.filled(cols, 0);
  for (int i = 0; i < dailyPlaylists.length; i++) {
    for (int j = 0; j < cols; j++) {
      totals[j] += dailyPlaylists[i][j];
    }
  }
  return totals;
}

@pragma('vm:entry-point')
void main() {
  assert(genrePlayCounts([[3, 1, 2], [1, 4, 0], [2, 2, 3]]).toString() == '[6, 7, 5]');
  assert(genrePlayCounts([[5]]).toString() == '[5]');
  assert(genrePlayCounts([]).toString() == '[]');
  print('All tests passed!');
}

