@pragma('vm:entry-point')
bool hasCriticalNormalBalance(List<List<Object>> samples) {
  final Map<String, List<List<Object>>> byType = {};
  for (final sample in samples) {
    final String type = sample[1] as String;
    byType.putIfAbsent(type, () => []).add(sample);
  }

  for (final group in byType.values) {
    final Set<String> criticalSensorIds = {};
    int normalCount = 0;
    for (final sample in group) {
      final double value = sample[2] as double;
      final String sensorId = sample[0] as String;
      if (value > 1.0) {
        criticalSensorIds.add(sensorId);
      } else {
        normalCount++;
      }
    }
    if (criticalSensorIds.isNotEmpty && normalCount > 0 && criticalSensorIds.length == normalCount) {
      return true;
    }
  }
  return false;
}

