  assert(hasCriticalNormalBalance([]) == false);
  assert(hasCriticalNormalBalance([['s1', 'temp', 2.0], ['s1', 'temp', 0.5]]) == true);
  assert(hasCriticalNormalBalance([['s1', 'temp', 2.0], ['s2', 'temp', 0.5]]) == true);
