double avgWifiSignalOverDuration(List<int> signalBins, int startDay, int numDays) {
  if (numDays <= 0) return 0.0;
  int total = 0;
  for (int i = startDay; i < startDay + numDays; i++) {
    if (i >= 0 && i < signalBins.length) {
