@pragma('vm:entry-point')
String highestGcWindow(String seq, int windowSize) {
  if (seq.isEmpty || windowSize <= 0) return '';
  if (windowSize >= seq.length) return seq;

  int maxGc = 0;
  int currentGc = 0;
  int bestStart = 0;

  for (int i = 0; i < windowSize; i++) {
    if (seq[i] == 'G' || seq[i] == 'C') currentGc++;
  }
  maxGc = currentGc;

  for (int i = windowSize; i < seq.length; i++) {
    if (seq[i] == 'G' || seq[i] == 'C') currentGc++;
    if (seq[i - windowSize] == 'G' || seq[i - windowSize] == 'C') currentGc--;
    if (currentGc > maxGc) {
      maxGc = currentGc;
      bestStart = i - windowSize + 1;
    }
  }

  return seq.substring(bestStart, bestStart + windowSize);
}

@pragma('vm:entry-point')
void main() {
  assert(highestGcWindow("AATTGGCC", 4) == "GGCC");
  assert(highestGcWindow("GCGC", 4) == "GCGC");
  assert(highestGcWindow("", 3) == "");
  print('All tests passed!');
}

tests:
