  final candidate = highestGcWindow;

  expect(candidate("AATTGGCC", 4), "GGCC");
  expect(candidate("GCAATTGC", 2), "GC");
  expect(candidate("ATATATAT", 3), "ATA");
  expect(candidate("", 5), "");
  expect(candidate("GCGC", 2), "GC");
