String lastActiveSession(List<String> logs) {
  List<String> stack = [];
  for (String line in logs) {
    if (line.startsWith('START ')) {
      stack.add(line.substring(6));
    } else if (line == 'END') {
      if (stack.isEmpty) return 'error';
      stack.removeLast();
    }
  }
  return stack.isEmpty ? 'idle' : stack.last;
}

