@pragma('vm:entry-point')
List<int> calculateDominantSatellitePerWindow(List<int> satellitePasses, int windowSize) {
  if (windowSize <= 0 || satellitePasses.isEmpty || windowSize > satellitePasses.length) {
    return [];
  }
  List<int> result = [];
  int n = satellitePasses.length;
  for (int i = 0; i <= n - windowSize; i++) {
    Map<int, int> freq = {};
    for (int j = i; j < i + windowSize; j++) {
      int sat = satellitePasses[j];
      freq[sat] = (freq[sat] ?? 0) + 1;
    }
    int maxFreq = 0;
    int dominant = 2147483647;
    freq.forEach((sat, f) {
      if (f > maxFreq || (f == maxFreq && sat < dominant)) {
        maxFreq = f;
        dominant = sat;
      }
    });
    result.add(dominant);
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateDominantSatellitePerWindow([5,5,5],1).toString() == '[5,5,5]');
  assert(calculateDominantSatellitePerWindow([],3).toString() == '[]');
  assert(calculateDominantSatellitePerWindow([1,2,2,1,3],2).length == 4);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = calculateDominantSatellitePerWindow;

