List<int> computeSkuChecksumBlocks(String skuSequence, int blockSize) {
  final result = <int>[];
  var sum = 0, count = 0;
  for (var i = 0; i < skuSequence.length; i++) {
    sum += skuSequence.codeUnitAt(i);
    if (++count == blockSize) {
      result.add(sum);
