@pragma('vm:entry-point')
int findTemperatureThreshold(List<List<int>> schedule, int requiredMinutes) {
  if (schedule.isEmpty) return 0;
  int minTemp = schedule[0][2];
  int maxTemp = schedule[0][2];
  for (var interval in schedule) {
    int t = interval[2];
    if (t < minTemp) minTemp = t;
    if (t > maxTemp) maxTemp = t;
  }
  int ans = minTemp - 1;
  int low = minTemp, high = maxTemp;
  while (low <= high) {
    int mid = (low + high) >> 1;
    int total = 0;
    for (var interval in schedule) {
      if (interval[2] >= mid) {
        total += interval[1] - interval[0];
      }
    }
    if (total >= requiredMinutes) {
      ans = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return ans;
}

@pragma('vm:entry-point')
void main() {
  assert(findTemperatureThreshold([[0,480,18],[480,720,22],[720,1080,20],[1080,1440,16]], 0) == 22);
  assert(findTemperatureThreshold([[0,480,18],[480,720,22],[720,1080,20],[1080,1440,16]], 1440) == 16);
  assert(findTemperatureThreshold([[0,1440,21]], 720) == 21);
