int totalItemCountFromRLE(String rle) {
  int total = 0;
  int i = 0;
  int len = rle.length;
  while (i < len) {
    while (i < len && (rle.codeUnitAt(i) < 48 || rle.codeUnitAt(i) > 57)) i++;
