String generateShelfNavigation(int px, int py, int x1, int y1, int x2, int y2) {
  int minX = x1 < x2 ? x1 : x2;
  int maxX = x1 > x2 ? x1 : x2;
  int minY = y1 < y2 ? y1 : y2;
  int maxY = y1 > y2 ? y1 : y2;

  int dx = 0;
  String dirX = "";
  if (px < minX) { dx = minX - px; dirX = "E"; } 
  else if (px > maxX) { dx = px - maxX; dirX = "W"; }

  int dy = 0;
  String dirY = "";
  if (py < minY) { dy = minY - py; dirY = "N"; } 
  else if (py > maxY) { dy = py - maxY; dirY = "S"; }

  int distance = dx + dy;
  String direction = distance == 0 ? "IN" : 
      (dirX.isEmpty ? dirY : (dirY.isEmpty ? dirX : dirY + dirX));

  return "Distance: $distance, Direction: $direction";
}

@pragma('vm:entry-point')
void main() {
  assert(generateShelfNavigation(15, 15, 10, 10, 20, 20) == 'Distance: 0, Direction: IN');
  assert(generateShelfNavigation(5, 5, 10, 10, 20, 20) == 'Distance: 10, Direction: NE');
  assert(generateShelfNavigation(0, 30, 10, 10, 20, 20) == 'Distance: 20, Direction: SE');
