@pragma('vm:entry-point')
List<int> categorizePasswordsByCompliance(List<String> passwords) {
  Map<int, int> frequency = {};
  for (final pw in passwords) {
    int satisfied = 0;
    // Length rule
    if (pw.length >= 8) satisfied++;
    // Count uppercase and digits
    int upperCount = 0;
    int digitCount = 0;
    for (final code in pw.codeUnits) {
      if (code >= 65 && code <= 90) {
        upperCount++;
      } else if (code >= 48 && code <= 57) {
        digitCount++;
      }
    }
    if (upperCount >= 2) satisfied++;
    if (digitCount >= 2) satisfied++;
    frequency[satisfied] = (frequency[satisfied] ?? 0) + 1;
  }
  final result = List.filled(4, 0);
  for (final entry in frequency.entries) {
    result[entry.key] = entry.value;
  }
  return result;
}

