@pragma('vm:entry-point')
String currentPhase(List<int> startTimes, int time) {
  if (startTimes.isEmpty || time < startTimes[0]) return "OFF";
  int lo = 0, hi = startTimes.length - 1, ans = 0;
  while (lo <= hi) {
    int mid = (lo + hi) ~/ 2;
    if (startTimes[mid] <= time) { ans = mid; lo = mid + 1; }
    else { hi = mid - 1; }
  }
  int m = ans % 3;
  return m == 0 ? "RED" : m == 1 ? "GREEN" : "YELLOW";
}

