@pragma('vm:entry-point')
int computeDiceRoundBonus(List<List<int>> grid) {
  if (grid.length < 2) return 0;
  int bonus = 0;
  int rows = grid.length;
  int cols = grid[0].length;
  for (int r = 0; r < rows - 1; r++) {
    for (int c = 0; c < cols; c++) {
      int curr = grid[r][c];
      if (curr == grid[r + 1][c]) {
        bonus += curr * 2;
      } else {
        bool matched = false;
        for (int nc = c - 1; nc <= c + 1; nc++) {
          if (nc >= 0 && nc < cols && grid[r + 1][nc] == curr) {
            matched = true;
            break;
          }
        }
        if (matched) bonus += 1;
      }
    }
  }
  return bonus;
}

@pragma('vm:entry-point')
void main() {
  assert(computeDiceRoundBonus([[1, 2], [2, 2]]) == 4);
  assert(computeDiceRoundBonus([[3, 3, 4], [3, 5, 3]]) == 7);
