@pragma('vm:entry-point')
int countDotsInMorseTyping(String commands) {
  List<String> mainStack = [];
  List<String> undoStack = [];
  for (int i = 0; i < commands.length; i++) {
    String ch = commands[i];
    if (ch == '.' || ch == '-') {
      mainStack.add(ch);
      undoStack.clear();
    } else if (ch == 'u') {
      if (mainStack.isNotEmpty) {
        String last = mainStack.removeLast();
        undoStack.add(last);
      }
    } else if (ch == 'r') {
      if (undoStack.isNotEmpty) {
        String last = undoStack.removeLast();
        mainStack.add(last);
      }
    }
  }
  return mainStack.where((c) => c == '.').length;
}

@pragma('vm:entry-point')
void main() {
  assert(countDotsInMorseTyping('') == 0);
  assert(countDotsInMorseTyping('.-.') == 2);
  assert(countDotsInMorseTyping('.-u') == 1);
  print('All tests passed!');
}

