List<int> countRowOverlaps(List<String> rows) {
  if (rows.isEmpty) return [];
  List<int> overlaps = [0]; // first row has no previous row
  for (int i = 1; i < rows.length; i++) {
    int count = 0;
    int len = rows[i].length < rows[i - 1].length ? rows[i].length : rows[i - 1].length;
    for (int j = 0; j < len; j++) {
      if (rows[i][j] == '#' && rows[i - 1][j] == '#') {
        count++;
      }
    }
    overlaps.add(count);
  }
  return overlaps;
}

