bool followsIngredientScaling(List<List<int>> recipeGrid, int scaleStep) {
  if (recipeGrid.isEmpty) {
    return true;
  }

  for (int r = 1; r < recipeGrid.length; r++) {
    if (recipeGrid[r].length != recipeGrid[0].length) {
      return false;
    }

    for (int c = 0; c < recipeGrid[r].length; c++) {
      if (recipeGrid[r][c] != recipeGrid[0][c] + (scaleStep * r)) {
        return false;
      }
    }
  }

  return true;
}

