bool detectsFinderPatternInModules(List<int> modules) {
  if (modules.length < 7) return false;
  int left = 0;
  int right = 6;
  while (right < modules.length) {
    bool matches = true;
    if (modules[left] != 1) matches = false;
    if (modules[left + 1] != 0) matches = false;
    if (modules[left + 2] != 1) matches = false;
    if (modules[left + 3] != 1) matches = false;
    if (modules[left + 4] != 1) matches = false;
    if (modules[left + 5] != 0) matches = false;
    if (modules[left + 6] != 1) matches = false;
    if (matches) return true;
    left++;
    right++;
  }
  return false;
}

