  assert(findPackageForScaledRecipe([100, 250, 500, 1000], 200, 1.5, 'Flour') == 'Buy 500g Flour');
  assert(findPackageForScaledRecipe([50, 100, 200], 300, 0.25, 'Sugar') == 'Buy 100g Sugar');
