List<int> sortTidesByProximity(List<int> tides, int referenceLevel) {
  List<int> result = List<int>.from(tides);
  result.sort((a, b) {
    int distA = (a - referenceLevel).abs();
    int distB = (b - referenceLevel).abs();
    if (distA != distB) return distA.compareTo(distB);
    return a.compareTo(b);
  });
  return result;
}

