@pragma('vm:entry-point')
String activeShowsOnDay(int day, List<List<int>> shows, List<int> blackouts) {
  for (int b in blackouts) {
    if (day == b) return "blackout";
  }
  List<int> active = [];
  for (int i = 0; i < shows.length; i++) {
    int start = shows[i][0];
    int cycle = shows[i][1];
    int duration = shows[i][2];
    if (day < start) continue;
    int offset = day - start;
    int posInCycle = offset % cycle;
    if (posInCycle < duration) {
      active.add(i);
    }
  }
  if (active.isEmpty) return "none";
  return active.join(",");
}

@pragma('vm:entry-point')
void main() {
  assert(activeShowsOnDay(3, [[0,7,2],[3,5,1],[1,10,3]], [5,12]) == "1,2");
  assert(activeShowsOnDay(8, [[0,7,2],[3,5,1],[1,10,3]], [5,12]) == "0,1");
