@pragma('vm:entry-point')
String trainTimetableUndoLog(List<String> log) {
  final stack = <int>[];
  var total = 0;
  for (final entry in log) {
    if (entry == 'UNDO') {
      if (stack.isNotEmpty) {
        total -= stack.removeLast();
      }
    } else {
      final minutes = int.parse(entry);
      total += minutes;
      stack.add(minutes);
    }
  }
  return total.toString();
}

