@pragma('vm:entry-point')
String sortPasswordViolationsBySeverity(List<String> violations) {
  if (violations.isEmpty) return '';
  int severityRank(String msg) {
    if (msg.startsWith('[CRITICAL]')) return 0;
    if (msg.startsWith('[WARNING]')) return 1;
    if (msg.startsWith('[INFO]')) return 2;
    return 3;
  }
  final sorted = List<String>.from(violations);
  sorted.sort((a, b) {
    final rankA = severityRank(a);
    final rankB = severityRank(b);
    if (rankA != rankB) return rankA.compareTo(rankB);
    return a.compareTo(b);
  });
  return sorted.join('|');
}

@pragma('vm:entry-point')
void main() {
  assert(sortPasswordViolationsBySeverity([]) == '');
  assert(sortPasswordViolationsBySeverity(['[INFO] too short', '[CRITICAL] no uppercase', '[WARNING] no digit', '[CRITICAL] no symbol']) == '[CRITICAL] no symbol|[CRITICAL] no uppercase|[WARNING] no digit|[INFO] too short');
