@pragma('vm:entry-point')
String resolveInventoryActions(List<String> actions) {
  final List<String> stack = [];
  for (final action in actions) {
    if (action.isEmpty) continue;
    final spaceIdx = action.indexOf(' ');
    final cmd = spaceIdx < 0 ? action : action.substring(0, spaceIdx);
    final arg = spaceIdx < 0 ? '' : action.substring(spaceIdx + 1);
    switch (cmd) {
      case 'PICKUP':
        if (arg.isNotEmpty) stack.add(arg);
        break;
      case 'DROP':
        if (stack.isNotEmpty) stack.removeLast();
        break;
      case 'COMBINE':
        if (stack.length >= 2) {
          final t = stack.removeLast();
          final s = stack.removeLast();
          stack.add('$s+$t');
        }
        break;
      case 'SORT':
        stack.sort();
        break;
      case 'PURGE':
        if (arg.isNotEmpty) stack.removeWhere((e) => e == arg);
        break;
    }
  }
  return stack.isEmpty ? 'EMPTY' : stack.join(',');
}

@pragma('vm:entry-point')
void main() {
  assert(resolveInventoryActions(<String>[]) == 'EMPTY');
  assert(resolveInventoryActions(<String>['PICKUP sword', 'PICKUP shield', 'COMBINE']) == 'sword+shield');
  assert(resolveInventoryActions(<String>['DROP', 'DROP']) == 'EMPTY');
  print('All tests passed!');
}

