@pragma('vm:entry-point')
List<int> optimizeThermostatSchedule(List<int> targets, int startTemp, int maxStep) {
  List<int> best = <int>[];
  int bestCost = -1;

  void search(int index, int currentTemp, List<int> path, int cost) {
    if (index == targets.length) {
      if (bestCost == -1 || cost < bestCost) {
        bestCost = cost;
        best = List<int>.from(path);
      }
      return;
    }

    int low = currentTemp - maxStep;
    int high = currentTemp + maxStep;

    for (int next = low; next <= high; next++) {
      int nextCost = cost + (targets[index] - next).abs();

      if (bestCost != -1 && nextCost > bestCost) {
        continue;
      }

      path.add(next);
      search(index + 1, next, path, nextCost);
      path.removeLast();
    }
  }

  search(0, startTemp, <int>[], 0);
  return best;
}

@pragma('vm:entry-point')
void main() {
  assert(optimizeThermostatSchedule(<int>[20, 22], 20, 1).toString() == '[20, 21]');
  assert(optimizeThermostatSchedule(<int>[], 18, 2).length == 0);
  assert(optimizeThermostatSchedule(<int>[19, 17, 16], 20, 2).toString() == '[19, 17, 16]');
  print('All tests passed!');
}

