int countSingletonSetpoints(List<int> schedule) {
  final counts = <int, int>{};
  var singletons = 0;
  for (final temp in schedule) {
    final previous = counts[temp] ?? 0;
    counts[temp] = previous + 1;
    if (previous == 0) {
      singletons++;
    } else if (previous == 1) {
      singletons--;
    }
  }
  return singletons;
}

