@pragma('vm:entry-point')
String roundCurrencyCents(String price) {
  String symbol = price[0];
  int dotIndex = price.indexOf('.');
  if (dotIndex == -1) {
    return '$price.00';
  }
  int dollars = int.parse(price.substring(1, dotIndex));
  String decimalStr = price.substring(dotIndex + 1);
  int totalCents;
  if (decimalStr.length <= 2) {
    totalCents = dollars * 100 + int.parse(decimalStr.padRight(2, '0'));
  } else {
    int centsBase = int.parse(decimalStr.substring(0, 2));
    int roundingDigit = int.parse(decimalStr[2]);
    totalCents = dollars * 100 + centsBase + (roundingDigit >= 5 ? 1 : 0);
  }
  int d = totalCents ~/ 100;
  int c = totalCents % 100;
  return '$symbol$d.${c.toString().padLeft(2, '0')}';
}

