@pragma('vm:entry-point')
List<int> extractQrDarkClusterStarts(String modules, int minClusterSize, int maxGapSize) {
  List<int> clusterStarts = [];
  List<int> clusterEnds = [];
  int i = 0;
  while (i < modules.length) {
    if (modules[i] == '1') {
      int start = i;
      while (i < modules.length && modules[i] == '1') {
        i++;
      }
      if (i - start >= minClusterSize) {
        clusterStarts.add(start);
        clusterEnds.add(i - 1);
      }
    } else {
      i++;
    }
  }
  if (clusterStarts.isEmpty) return [];
  List<int> result = [clusterStarts[0]];
  for (int j = 1; j < clusterStarts.length; j++) {
    int gap = clusterStarts[j] - clusterEnds[j - 1] - 1;
    if (gap > maxGapSize) {
      result.add(clusterStarts[j]);
    }
  }
  return result;
}

