String mazeKeyCell(int rows, int cols) {
  int total = rows * cols;
  if (total < 2) return "none";
  for (int n = total; n >= 2; n--) {
    bool isPrime = true;
    for (int d = 2; d * d <= n; d++) {
      if (n % d == 0) {
        isPrime = false;
