@pragma('vm:entry-point')
int asciiBoxNestingSum(List<String> rows) {
  int totalScore = 0;
  for (String row in rows) {
    List<List<int>> stack = [];
    for (int i = 0; i < row.length; i++) {
      String ch = row[i];
      if (ch == '[') {
        stack.add([1, stack.length]);
      } else if (ch == '{') {
        stack.add([2, stack.length * 2]);
      } else if (ch == ']' && stack.isNotEmpty && stack.last[0] == 1) {
        totalScore += stack.removeLast()[1];
      } else if (ch == '}' && stack.isNotEmpty && stack.last[0] == 2) {
        totalScore += stack.removeLast()[1];
      }
    }
  }
  return totalScore;
}

@pragma('vm:entry-point')
