@pragma('vm:entry-point')
List<int> runLengthEncodeSeating(String row) {
  List<int> result = [];
  if (row.isEmpty) return result;
  int count = 1;
  int type = row[0] == 'X' ? 1 : 0;
  for (int i = 1; i < row.length; i++) {
    int currentType = row[i] == 'X' ? 1 : 0;
    if (currentType == type) {
      count++;
    } else {
      result.add(count);
      result.add(type);
      count = 1;
      type = currentType;
    }
  }
  result.add(count);
  result.add(type);
  return result;
}

@pragma('vm:entry-point')
