/// Returns true if two seeds can meet in the given round of a single-elimination
/// tournament with a fixed linear draw (first round: 1vs2, 3vs4, 5vs6, ...).
bool canMeetInRound(int seedA, int seedB, int round, int totalTeams) {
  // Convert to zero-based positions and compute XOR
  int x = (seedA - 1) ^ (seedB - 1);
  // The round they would meet equals the bit-length of the XOR value.
  return x != 0 && x.bitLength == round;
}

