@pragma('vm:entry-point')
String extractNormalizedChessSquares(String input) {
  if (input.isEmpty) return '';
  List<String> squares = [];
  int i = 0;
  String lower = input.toLowerCase();
  while (i < lower.length) {
    while (i < lower.length && !(lower.codeUnitAt(i) >= 97 && lower.codeUnitAt(i) <= 104)) {
      i++;
    }
    if (i >= lower.length) break;
    int file = lower.codeUnitAt(i);
    i++;
    if (i < lower.length) {
      int rankCode = lower.codeUnitAt(i);
      if (rankCode >= 49 && rankCode <= 56) {
        String sq = String.fromCharCode(file) + String.fromCharCode(rankCode);
        squares.add(sq);
        i++;
        continue;
      }
    }
  }
  return squares.join(' ');
}

