int strongestPasswordLength(List<String> passwords) {
  if (passwords.isEmpty) return 0;
  List<String> sorted = List<String>.from(passwords);
  sorted.sort((a, b) {
    int digitsA = RegExp(r'[0-9]').allMatches(a).length;
    int digitsB = RegExp(r'[0-9]').allMatches(b).length;
    if (digitsA != digitsB) return digitsA.compareTo(digitsB);
    if (a.length != b.length) return a.length.compareTo(b.length);
    return a.compareTo(b);
  });
  return sorted.last.length;
}

