@pragma('vm:entry-point')
List<int> findCandidateViabilitySplit(List<int> sortedVotes, int threshold) {
  int left = 0;
  int right = sortedVotes.length;
  while (left < right) {
    int mid = left + ((right - left) >> 1);
    if (sortedVotes[mid] < threshold) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return [left, sortedVotes.length - left];
}

@pragma('vm:entry-point')
void main() {
  assert(findCandidateViabilitySplit([10, 20, 30, 40, 50], 25).toString() == '[2, 3]');
  assert(findCandidateViabilitySplit([], 10).toString() == '[0, 0]');
  assert(findCandidateViabilitySplit([5, 5, 5], 5).toString() == '[0, 3]');
  print('All tests passed!');
}

tests:
