@pragma('vm:entry-point')
List<String> prioritizeChargeOrder(List<String> cycleLogs) {
  List<List<String>> parsed = cycleLogs.map((s) => s.split(':')).toList();
  parsed.sort((a, b) {
    int capA = int.parse(a[2]);
    int capB = int.parse(b[2]);
    if (capA != capB) return capB.compareTo(capA);
    int cycA = int.parse(a[1]);
    int cycB = int.parse(b[1]);
    if (cycA != cycB) return cycB.compareTo(cycA);
    return a[0].compareTo(b[0]);
  });
  return parsed.map((parts) => parts.join(':')).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(prioritizeChargeOrder(["a:10:80"]).toString() == "[a:10:80]");
  assert(prioritizeChargeOrder(<String>[]).toString() == "[]");
