@pragma('vm:entry-point')
bool validateTelemetryBurstLog(List<String> log) {
  // A burst opens with 'START' and closes with 'END'.
  // Samples look like 'S:<value>' and must appear inside an open burst.
  // Every burst must contain at least one sample or one nested burst.
  final stack = <int>[];
  for (final entry in log) {
    if (entry == 'START') {
      stack.add(0);
    } else if (entry == 'END') {
      if (stack.isEmpty || stack.last == 0) return false;
      stack.removeLast();
      if (stack.isNotEmpty) {
        stack[stack.length - 1] = stack.last + 1;
      }
    } else if (entry.startsWith('S:')) {
      if (stack.isEmpty) return false;
      stack[stack.length - 1] = stack.last + 1;
    } else {
      return false;
    }
  }
  return stack.isEmpty;
}

@pragma('vm:entry-point')
void main() {
  assert(validateTelemetryBurstLog(['START', 'S:3', 'END']) == true);
  assert(validateTelemetryBurstLog(['START', 'END']) == false);
  assert(validateTelemetryBurstLog(['S:5']) == false);
