@pragma('vm:entry-point')
String findWidestSolidSegments(String asciiArt, int maxGaps) {
  List<String> rows = asciiArt.split('\n');
  List<String> results = [];
  for (int i = 0; i < rows.length; i++) {
    String row = rows[i];
    if (row.isEmpty) {
      results.add('$i:0');
      continue;
    }
    int maxLen = 0;
    int left = 0;
    int spaces = 0;
    for (int right = 0; right < row.length; right++) {
      if (row[right] == ' ') {
        spaces++;
      }
      while (spaces > maxGaps) {
        if (row[left] == ' ') {
          spaces--;
        }
        left++;
      }
      int windowLen = right - left + 1;
      if (windowLen > maxLen) {
        maxLen = windowLen;
      }
    }
    results.add('$i:$maxLen');
  }
  return results.join(';');
}

@pragma('vm:entry-point')
void main() {
  assert(findWidestSolidSegments('hello world', 1) == '0:11');
  assert(findWidestSolidSegments('foo  bar', 0) == '0:3');
  assert(findWidestSolidSegments('abc\ndef', 0) == '0:3;1:3');
  print('All tests passed!');
}

