@pragma('vm:entry-point')
List<int> findUniformBatchSizes(List<int> shipmentQuantities) {
  if (shipmentQuantities.isEmpty) return [];

  int gcdVal = shipmentQuantities[0].abs();
  for (int i = 1; i < shipmentQuantities.length; i++) {
    int b = shipmentQuantities[i].abs();
    while (b != 0) {
      int t = b;
      b = gcdVal % b;
      gcdVal = t;
    }
  }

  if (gcdVal <= 1) return [];

  List<int> divisors = [];
  for (int i = 2; i * i <= gcdVal; i++) {
    if (gcdVal % i == 0) {
      divisors.add(i);
      if (i != gcdVal ~/ i) {
        divisors.add(gcdVal ~/ i);
      }
    }
  }
  divisors.add(gcdVal);

  divisors.sort();
  return divisors;
}

