List<String> passwordRunChecks(List<String> passwords) {
  List<String> result = [];
  for (String password in passwords) {
    if (password.isEmpty) {
      result.add('weak');
      continue;
    }
    List<int> dp = List.filled(password.length, 1);
    int best = 1;
    for (int i = 1; i < password.length; i++) {
      dp[i] = password[i] != password[i - 1] ? dp[i - 1] + 1 : 1;
      if (dp[i] > best) best = dp[i];
    }
    result.add(best >= 4 ? 'strong' : 'weak');
  }
  return result;
}

