  assert(planElevatorStops([5, 2, 8, 3], 1, 1).toString() == '[2, 3, 5, 8]');
  assert(planElevatorStops([5, 2, 8, 3], 10, -1).toString() == '[8, 5, 3, 2]');
  assert(planElevatorStops([4, 5, 2], 4, 1).toString() == '[4, 5, 2]');
  print('All tests passed!');
}

