@pragma('vm:entry-point')
int simulateBatteryCycles(List<double> chargeLevels) {
  if (chargeLevels.isEmpty) return 0;

  int cycles = 0;
  double currentCharge = 0.0;
  bool isCharging = true;
  bool wasDischarging = false;

  for (int i = 0; i < chargeLevels.length; i++) {
    double target = chargeLevels[i];
    if (target < 0) target = 0.0;
    if (target > 1) target = 1.0;

    if (isCharging) {
      if (target >= 0.9) {
        isCharging = false;
        cycles++;
        currentCharge = target;
      } else {
        currentCharge = target;
      }
    } else {
      if (target <= 0.2) {
        isCharging = true;
        currentCharge = target;
      } else {
        if (wasDischarging && target < currentCharge - 0.05) {
          // interrupted discharge, counts as partial cycle
          if (currentCharge >= 0.9) cycles++;
          currentCharge = target;
          isCharging = false;
          wasDischarging = false;
        } else {
          currentCharge = target;
          wasDischarging = true;
        }
      }
    }
  }

  if (!isCharging && currentCharge < 0.2) cycles++;

  return cycles;
}

@pragma('vm:entry-point')
