  assert(longestValidLogWindow(["INFO", "ERROR", "INFO", "WARN", "ERROR", "INFO"], 1) == "0:3");
  assert(longestValidLogWindow(["ERROR", "ERROR", "ERROR"], 2) == "0:1");
