int kthSmallestAbsAmount(List<int> transactions, int k) {
  if (transactions.isEmpty || k < 1 || k > transactions.length) {
    return -1;
  }
  int minAbs = transactions[0].abs();
  int maxAbs = minAbs;
  for (int t in transactions) {
    int a = t.abs();
    if (a < minAbs) minAbs = a;
    if (a > maxAbs) maxAbs = a;
  }
  int low = minAbs;
  int high = maxAbs;
  int candidate = -1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    int count = 0;
    for (int t in transactions) {
      if (t.abs() <= mid) count++;
    }
    if (count >= k) {
      candidate = mid;
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  return candidate;
}

