List<String> longestNonDecreasingLogSegment(List<String> logLines) {
  if (logLines.isEmpty) return [];
  List<int> dp = List.filled(logLines.length, 1);
  for (int i = 1; i < logLines.length; i++) {
    if (logLines[i].length >= logLines[i - 1].length) {
      dp[i] = dp[i - 1] + 1;
    }
  }
  int maxLen = dp.reduce((a, b) => a > b ? a : b);
  int maxIdx = dp.indexOf(maxLen);
  return logLines.sublist(maxIdx - maxLen + 1, maxIdx + 1);
}

@pragma('vm:entry-point')
void main() {
  assert(longestNonDecreasingLogSegment(["a", "bb", "ccc"]).length == 3);
  assert(longestNonDecreasingLogSegment([]).length == 0);
