bool hasSubarrayWithBrightnessSum(List<int> pixels, int targetSum) {
  int left = 0;
  int currentSum = 0;
  for (int right = 0; right < pixels.length; right++) {
    currentSum += pixels[right];
    while (currentSum > targetSum && left <= right) {
      currentSum -= pixels[left];
      left++;
    }
    if (currentSum == targetSum) {
      return true;
    }
  }
  return false;
}

