  assert(countPlayersWithDominanceScore(['A:B', 'A:C', 'A:B', 'B:C'], 6) == 1);
  assert(countPlayersWithDominanceScore(['X:Y', 'Y:Z', 'Z:X'], 1) == 3);
  assert(countPlayersWithDominanceScore([], 0) == 0);
