double asciiRowAverageSlope(String row) {
  double total = 0.0;
  int count = 0;
  for (int i = 0; i < row.length; i++) {
    String c = row[i];
    if (c == '/') { total += 0.5; count++; }
    else if (c == '\\') { total -= 0.5; count++; }
    else if (c == '-') { count++; }
  }
  if (count == 0) return 0.0;
  return total / count;
}

