String seatingBlockReport(List<List<String>> chart) {
  if (chart.isEmpty) return "";
  List<String> rows = [];
  for (var row in chart) {
    List<String> blocks = [];
    int count = 0;
    for (var seat in row) {
      if (seat == ".") {
        count++;
      } else {
        if (count > 0) {
          blocks.add(count.toString());
          count = 0;
        }
      }
    }
    if (count > 0) {
      blocks.add(count.toString());
    }
    rows.add(blocks.isEmpty ? "NONE" : blocks.join("|"));
  }
  return rows.join("\n");
}

