@pragma('vm:entry-point')
List<int> findDiscountRoundedIndices(List<int> prices, int target) {
  int l = 0, r = prices.length - 1;
  while (l <= r) {
    int m = (l + r) ~/ 2, val = (prices[m] * 9 + 5) ~/ 10;
    if (val == target) {
      int s = m, e = m;
      while (s > 0 && (prices[s - 1] * 9 + 5) ~/ 10 == target) s--;
      while (e + 1 < prices.length && (prices[e + 1] * 9 + 5) ~/ 10 == target) e++;
      return [s, e];
    }
    val < target ? l = m + 1 : r = m - 1;
  }
  return [-1, -1];
}

@pragma('vm:entry-point')
