@pragma('vm:entry-point')
List<int> sortPasswordCharCodes(List<int> codes) {
  int rank(int c) {
    if (c >= 48 && c <= 57) return 0;
    if (c >= 65 && c <= 90) return 1;
    if (c >= 97 && c <= 122) return 2;
    return 3;
  }
  final result = List<int>.from(codes);
  result.sort((a, b) {
    final ra = rank(a);
    final rb = rank(b);
    return ra != rb ? ra - rb : a - b;
  });
  return result;
}

