List<int> elevatorArrivalDays(List<int> requests) {
  List<int> arrivals = [];
  int currentFloor = 0;
  int currentDay = 0;
  for (int i = 0; i < requests.length; i += 2) {
    int requestDay = requests[i];
    int floor = requests[i + 1];
    int travelDays = (floor - currentFloor).abs();
    int arrivalDay = currentDay + travelDays > requestDay ? currentDay + travelDays : requestDay;
    arrivals.add(arrivalDay);
    currentDay = arrivalDay;
    currentFloor = floor;
  }
  return arrivals;
}

