List<int> bestTheaterViewingSection(List<int> seats, int maxReserved) {
  int left = 0;
  int reservedCount = 0;
  int bestStart = -1;
  int bestEnd = -1;
  int bestLength = 0;

  for (int right = 0; right < seats.length; right++) {
    if (seats[right] == 1) {
      reservedCount++;
    }

    while (reservedCount > maxReserved && left <= right) {
      if (seats[left] == 1) {
        reservedCount--;
      }
      left++;
    }

    int currentLength = right - left + 1;

    if (currentLength > bestLength) {
      bestLength = currentLength;
      bestStart = left;
      bestEnd = right;
    }
  }

  return <int>[bestStart, bestEnd, bestLength];
}

