List<int> findTidePools(List<List<int>> grid) {
  if (grid.length < 3) return [];
  int rows = grid.length;
  int cols = grid[0].length;
  if (cols < 3) return [];
  for (var row in grid) {
    if (row.length != cols) return [];
  }
  List<int> pools = [];
  for (int i = 1; i < rows - 1; i++) {
    for (int j = 1; j < cols - 1; j++) {
      int val = grid[i][j];
      if (val < grid[i-1][j] && val < grid[i+1][j] && val < grid[i][j-1] && val < grid[i][j+1]) {
        pools.add(val);
      }
    }
  }
  return pools;
}

