int barcodeDigitSumIndex(List<int> barcodes, int targetSum) {
  if (barcodes.isEmpty) return -1;
  int digitSum(int n) {
    int sum = 0;
    while (n > 0) { sum += n % 10; n ~/= 10; }
    return sum;
  }
  List<int> sorted = List.from(barcodes);
  sorted.sort((a, b) => digitSum(a).compareTo(digitSum(b)));
  for (int i = 0; i < sorted.length; i++) {
    if (digitSum(sorted[i]) == targetSum) return i;
  }
  return -1;
}

