@pragma('vm:entry-point')
bool isValidChargeCycleCode(String record) {
  int split = record.indexOf('#');
  if (split <= 0 || split == record.length - 1) {
    return false;
  }
  int total = 0;
  for (int i = 0; i < split; i += 2) {
    if (i + 1 >= split) {
      return false;
    }
    int count = record.codeUnitAt(i) - 48;
    String state = record[i + 1];
    if (count < 0 || count > 9 || (state != 'C' && state != 'D')) {
      return false;
    }
    total += count;
  }
  return total == int.parse(record.substring(split + 1));
}

@pragma('vm:entry-point')
void main() {
  assert(isValidChargeCycleCode('3C2D#5') == true);
  assert(isValidChargeCycleCode('4C1D#3') == false);
  assert(isValidChargeCycleCode('7D#7') == true);
  print('All tests passed!');
