@pragma('vm:entry-point')
String knightReachableSquares(String start, int moves) {
  Set<String> visited = {};

  void dfs(String pos, int remaining) {
    if (remaining == 0) {
      visited.add(pos);
      return;
    }
    int c = pos.codeUnitAt(0) - 'a'.codeUnitAt(0) + 1;
    int r = int.parse(pos[1]);
    List<List<int>> knightMoves = [
      [1, 2], [1, -2], [-1, 2], [-1, -2],
      [2, 1], [2, -1], [-2, 1], [-2, -1]
    ];
    for (List<int> move in knightMoves) {
      int nc = c + move[0];
      int nr = r + move[1];
      if (nc >= 1 && nc <= 8 && nr >= 1 && nr <= 8) {
        String nextPos = '${String.fromCharCode('a'.codeUnitAt(0) + nc - 1)}$nr';
        dfs(nextPos, remaining - 1);
      }
    }
  }

  dfs(start, moves);
  List<String> result = visited.toList()..sort();
  return result.join(',');
}

