List<int> detectConsistentArtSpans(List<String> rows) {
  if (rows.isEmpty || rows[0].isEmpty) return [];
  int n = rows[0].length;
  for (String r in rows) if (r.length != n) return [];
  List<int> spans = [];
  int left = 0;
  while (left < n) {
    int right = left;
    bool consistent = true;
    while (right < n) {
      String ch = rows[0][right];
      bool colOk = true;
      for (String row in rows) {
        if (row[right] != ch) { colOk = false; break; }
      }
      if (!colOk) break;
      right++;
    }
    if (right > left) {
      spans.add(right - left);
      left = right;
    } else {
      left++;
    }
  }
  return spans;
}

