List<int> calculateTransferWaits(List<int> lineA, List<int> lineB, int minTransfer, int maxTransfer) {
  if (lineB.isEmpty) {
    return List.filled(lineA.length, -1);
  }

  List<int> aSorted = List.from(lineA)..sort();
  List<int> bSorted = List.from(lineB)..sort();
  List<int> waits = [];

  for (int departA in aSorted) {
    int target = departA + minTransfer;
    int wait = -1;

    for (int departB in bSorted) {
      if (departB >= target) {
        wait = departB - departA;
        break;
      }
    }

    if (wait == -1) {
      wait = (1440 - departA) + bSorted.first;
    }

    if (wait > maxTransfer) {
      waits.add(-1);
    } else {
      waits.add(wait);
    }
  }

  return waits;
}

