List<int> locateTransactionsInRange(List<int> entries, int lower, int upper) {
  int n = entries.length;
  int start = 0, end = n;
  while (start < end) {
    int mid = (start + end) ~/ 2;
    if (entries[mid] < lower) start = mid + 1; else end = mid;
  }
  int left = start; start = 0; end = n;
  while (start < end) {
    int mid = (start + end) ~/ 2;
    if (entries[mid] <= upper) start = mid + 1; else end = mid;
  }
  int right = start;
  List<int> res = [];
  for (int i = left; i < right; i++) res.add(i);
  return res;
}

