bool canArrangeBalancedShelves(List<int> shelfCodes) {
  int n = shelfCodes.length;
  if (n == 0) return true;
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true;
  for (int i = 1; i <= n; i++) {
    int currentSum = 0;
    for (int j = i - 1; j >= 0; j--) {
      currentSum += shelfCodes[j];
      if (currentSum % 2 == 0 && dp[j]) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[n];
}

