@pragma('vm:entry-point')
String findBucketForKthItem(List<int> bucketCapacities, int k) {
  if (k <= 0) return "Invalid";
  int n = bucketCapacities.length;
  if (n == 0) return "Overflow";

  List<int> prefix = List.filled(n, 0);
  int sum = 0;
  for (int i = 0; i < n; i++) {
    sum += bucketCapacities[i];
    prefix[i] = sum;
  }

  if (k > sum) return "Overflow";

  int left = 0;
  int right = n - 1;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (prefix[mid] < k) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }

  int bucketIndex = left;
  int previousSum = (bucketIndex == 0) ? 0 : prefix[bucketIndex - 1];
  int remaining = bucketCapacities[bucketIndex] - (k - previousSum);

  return "Bucket $bucketIndex, $remaining remaining";
}

@pragma('vm:entry-point')
void main() {
  assert(findBucketForKthItem([2, 5, 3], 3) == 'Bucket 1, 4 remaining');
  assert(findBucketForKthItem([10], 5) == 'Bucket 0, 5 remaining');
