bool isScalingOrderPreserved(List<double> original, List<double> scaled) {
  if (original.length != scaled.length) return false;
  if (original.isEmpty) return true;
  List<int> originalOrder = List.generate(original.length, (i) => i)
    ..sort((a, b) => original[a].compareTo(original[b]));
  List<int> scaledOrder = List.generate(scaled.length, (i) => i)
    ..sort((a, b) => scaled[a].compareTo(scaled[b]));
  for (int i = 0; i < originalOrder.length; i++) {
    if (originalOrder[i] != scaledOrder[i]) return false;
