int countDnaTransitionSteps(List<String> fragments) {
  int total = 0;

  for (final frag in fragments) {
    if (frag.isEmpty) continue;

    final deduped = <String>[frag[0]];
    for (int i = 1; i < frag.length; i++) {
      if (frag[i] != frag[i - 1]) {
        deduped.add(frag[i]);
      }
    }

    for (int i = 1; i < deduped.length; i++) {
      final a = deduped[i - 1];
      final b = deduped[i];
      final aPurine = a == 'A' || a == 'G';
      final bPurine = b == 'A' || b == 'G';
      final aPyrimidine = a == 'C' || a == 'T';
      final bPyrimidine = b == 'C' || b == 'T';

      if ((aPurine && bPurine) || (aPyrimidine && bPyrimidine)) {
        total++;
      }
    }
  }

  return total;
}

