bool hasAdjacentOrOverlappingCards(List<List<int>> deck) {
  final occupied = <String>{};
  for (final card in deck) {
    final x = card[0];
    final y = card[1];
    final key = '$x,$y';
    if (occupied.contains(key)) return true;
    if (occupied.contains('${x + 1},$y') ||
        occupied.contains('${x - 1},$y') ||
        occupied.contains('$x,${y + 1}') ||
        occupied.contains('$x,${y - 1}')) return true;
    occupied.add(key);
  }
  return false;
}

