String dominantAsciiRow(List<String> rows) {
  if (rows.isEmpty) return 'empty';
  final counts = <String, int>{};
  String? bestRow;
  var bestCount = 0;
  for (final row in rows) {
    final c = (counts[row] ?? 0) + 1;
    counts[row] = c;
    if (c > bestCount || (c == bestCount && (bestRow == null || row.compareTo(bestRow) < 0))) {
      bestRow = row;
      bestCount = c;
    }
  }
  return '$bestRow|$bestCount';
}

