@pragma('vm:entry-point')
List<int> squaresForGameDuration(int startSquare, int duration) {
  List<int> squares = [];
  int current = startSquare % 64;
  if (current < 0) current += 64;
  int step = 1;
  for (int day = 0; day < duration; day++) {
    squares.add(current);
    if (day % 2 == 0) {
      step = 2;
    } else {
      step = 1;
    }
    current += step;
    if (current > 63) {
      current -= 64;
    }
  }
  return squares;
}

