@pragma('vm:entry-point')
int barcodeMissingDigit(List<int> digits) {
  int missingCount = 0;
  int missingIndex = -1;

  for (int i = 0; i < digits.length; i++) {
    if (digits[i] == -1) {
      missingCount++;
      missingIndex = i;
    }
  }

  if (missingCount == 0) {
    int sum = 0;
    for (int i = 0; i < digits.length; i++) {
      int weight = (i % 2 == 0) ? 1 : 3;
      sum += digits[i] * weight;
    }
    return (sum % 10 == 0) ? -1 : -2;
  }

  if (missingCount > 1) {
    return -3;
  }

  int partialSum = 0;
  int weight = (missingIndex % 2 == 0) ? 1 : 3;

  for (int i = 0; i < digits.length; i++) {
    if (i != missingIndex) {
      int w = (i % 2 == 0) ? 1 : 3;
      partialSum += digits[i] * w;
    }
  }

  int needed = (10 - partialSum % 10) % 10;

  for (int d = 0; d <= 9; d++) {
    if ((d * weight) % 10 == needed) {
      return d;
    }
  }

  return -2;
}

@pragma('vm:entry-point')
void main() {
  assert(barcodeMissingDigit([9, 7, 8, 0, 3, 0, 6, 4, 0, 6, 1, 5, -1]) == 7);
  assert(barcodeMissingDigit([9, 7, 8, 0, 3, 0, 6, 4, 0, 6, 1, 5, 7]) == -1);
