@pragma('vm:entry-point')
int longestStableLogWindow(List<String> logs, int maxErrors) {
  // Returns the length of the longest contiguous run of log lines
  // that contains at most maxErrors lines marked with "ERROR".
  int left = 0;
  int errorCount = 0;
  int best = 0;
  for (int right = 0; right < logs.length; right++) {
    if (logs[right].contains('ERROR')) {
      errorCount++;
    }
    while (errorCount > maxErrors && left <= right) {
      if (logs[left].contains('ERROR')) {
        errorCount--;
      }
      left++;
    }
    int windowSize = right - left + 1;
    if (windowSize > best) {
      best = windowSize;
    }
  }
  return best;
}

@pragma('vm:entry-point')
void main() {
  assert(longestStableLogWindow(['INFO a', 'ERROR b', 'INFO c', 'INFO d', 'ERROR e', 'INFO f'], 1) == 4);
  assert(longestStableLogWindow(['INFO a', 'ERROR b', 'INFO c', 'INFO d', 'ERROR e', 'INFO f'], 0) == 2);
