  final candidate = shelfStatus;

  expect(candidate([], 0), "EMPTY");
  expect(candidate([10], 0), "SHELF:0010001000001010");
  expect(candidate([0, 0, 0], 1), "SHELF:0000000000000000");
  expect(candidate([15, 30], 8), "SHELF:0100110011111101");
  expect(candidate([1, 2, 4, 8, 16], 16), "SHELF:1010000000011110");
}

