@pragma('vm:entry-point')
int findKthEnchantment(List<List<int>> slots, int k) {
  if (slots.isEmpty || k <= 0) return -1;
  int lo = 2147483647;
  int hi = -2147483648;
  int total = 0;
  for (var slot in slots) {
    if (slot.isEmpty) continue;
    total += slot.length;
    if (slot.first < lo) lo = slot.first;
    if (slot.last > hi) hi = slot.last;
  }
  if (total < k || total == 0) return -1;
  int ans = hi;
  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    int count = 0;
    for (var slot in slots) {
      if (slot.isEmpty) continue;
      int left = 0, right = slot.length;
      while (left < right) {
        int m = left + (right - left) ~/ 2;
        if (slot[m] <= mid) {
          left = m + 1;
        } else {
          right = m;
        }
      }
      count += left;
    }
    if (count >= k) {
      ans = mid;
      hi = mid - 1;
    } else {
      lo = mid + 1;
    }
  }
  return ans;
}

@pragma('vm:entry-point')
