List<int> dnaPackedInts(String dna, int basesPerInt) {
  const code = {'A': 0, 'C': 1, 'G': 2, 'T': 3};
  List<int> result = [];
  int packed = 0, count = 0;
  for (int i = 0; i < dna.length; i++) {
    packed |= (code[dna[i]] ?? 0) << (count * 2);
    count++;
    if (count == basesPerInt || i == dna.length - 1) {
      result.add(packed);
      packed = 0;
      count = 0;
    }
  }
  return result;
}

