bool isValidPacketTree(List<int> packets) {
  bool check(int i) {
    if (i >= packets.length) return true;
    int left = 2 * i + 1;
    int right = 2 * i + 2;
    bool hasLeft = left < packets.length;
    bool hasRight = right < packets.length;
    if (!hasLeft && !hasRight) return true; // leaf
    int sum = 0;
    if (hasLeft) sum += packets[left];
    if (hasRight) sum += packets[right];
    if (packets[i] != sum) return false;
    return check(left) && check(right);
  }
  return check(0);
}

