int totalScaledVowelIngredientMass(List<String> ingredients, int servings, Map<String, int> baseGrams) {
  int total = 0;
  for (final String ingredient in ingredients) {
    final int? base = baseGrams[ingredient];
    if (base == null) continue;
    if (ingredient.isEmpty) continue;
    final String first = ingredient[0].toLowerCase();
    if (first != 'a' && first != 'e' && first != 'i' && first != 'o' && first != 'u') {
      continue;
    }
    int scaled = base * servings;
    if (scaled > 50) {
      scaled = ((scaled + 24) ~/ 25) * 25;
