bool isPacketBatchValid(List<int> packetSizes, int maxPacketSize) {
  if (packetSizes.isEmpty || maxPacketSize <= 0) return false;
  int totalSize = packetSizes.fold(0, (sum, size) => sum + size);
  bool hasUniqueSizes = packetSizes.toSet().length == packetSizes.length;
  bool allWithinLimit = packetSizes.every((size) => size > 0 && size <= maxPacketSize);
  return totalSize % maxPacketSize == 0 && hasUniqueSizes && allWithinLimit;
}

