@pragma('vm:entry-point')
String findKthSmallestCycleCount(List<int> cycleCounts, int k) {
  List<int> arr = List.from(cycleCounts);
  if (k < 1 || k > arr.length) return "Invalid k";
  int left = 0, right = arr.length - 1, kIndex = k - 1;
  while (true) {
    int pivot = arr[right];
    int i = left;
    for (int j = left; j < right; j++) {
      if (arr[j] <= pivot) {
        int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp; i++;
      }
    }
    int tmp = arr[i]; arr[i] = arr[right]; arr[right] = tmp;
    if (kIndex == i) break;
    if (kIndex < i) right = i - 1;
    else left = i + 1;
  }
  return "The ${k}th smallest cycle count is ${arr[kIndex]}";
}

@pragma('vm:entry-point')
void main() {
  assert(findKthSmallestCycleCount([100, 50, 200], 1) == "The 1th smallest cycle count is 50");
  assert(findKthSmallestCycleCount([100, 50, 200], 2) == "The 2th smallest cycle count is 100");
  assert(findKthSmallestCycleCount([100, 50, 200], 3) == "The 3th smallest cycle count is 200");
