@pragma('vm:entry-point')
List<int> summationIntervalsOfLogLines(int dayStart, int dayEnd, List<int> lineCounts) {
  if (dayStart < 1 || dayEnd < 1 || dayEnd <= dayStart || lineCounts.isEmpty) {
    return [0, 0];
  }
  int totalDays = lineCounts.length;
  int intervalLength = dayEnd - dayStart;
  if (intervalLength > totalDays) {
    return [0, 0];
  }
  int maxSum = 0;
  int bestStartIndex = 0;
  for (int i = 0; i <= totalDays - intervalLength; i++) {
    int currentSum = 0;
    int endIdx = i + intervalLength;
    for (int j = i; j < endIdx; j++) {
      currentSum += lineCounts[j];
    }
    if (currentSum > maxSum) {
      maxSum = currentSum;
      bestStartIndex = i;
    }
  }
  int originalStartDay = dayStart + bestStartIndex;
  int originalEndDay = originalStartDay + intervalLength - 1;
  return [maxSum, originalStartDay, originalEndDay];
}

@pragma('vm:entry-point')
void main() {
  assert(summationIntervalsOfLogLines(2, 4, [5, 3, 8, 1, 4]).toString() == '[11, 2, 3]');
  assert(summationIntervalsOfLogLines(1, 3, [10, 20, 30, 40]).toString() == '[30, 1, 2]');
