String elevatorRouteSummary(List<List<int>> requestGrid) {
  List<String> results = [];
  for (int shaft = 0; shaft < requestGrid.length; shaft++) {
    int highestFloor = -1;
    for (int floor = 0; floor < requestGrid[shaft].length; floor++) {
      if (requestGrid[shaft][floor] > 0) {
        highestFloor = floor;
      }
    }
    if (highestFloor == -1) {
      results.add('S${shaft}->none');
    } else {
      results.add('S${shaft}->F${highestFloor}');
