@pragma('vm:entry-point')
int sensorEnergyChecksum(String encoded) {
  if (encoded.length % 2 != 0) return -1;
  int totalEnergy = 0;
  for (int i = 0; i < encoded.length; i += 2) {
    int charCode = encoded.codeUnitAt(i);
    if (charCode < 65 || charCode > 90) return -1;
    int digitCode = encoded.codeUnitAt(i + 1);
    if (digitCode < 49 || digitCode > 57) return -1;
    int sensorValue = charCode - 64;
    int count = digitCode - 48;
    totalEnergy += sensorValue * count;
  }
  int result = totalEnergy;
  while (result > 9) {
    int sumDigits = 0;
    int temp = result;
    while (temp > 0) {
      sumDigits += temp % 10;
      temp ~/= 10;
    }
    result = sumDigits;
  }
  return result;
}

@pragma('vm:entry-point')
