@pragma('vm:entry-point')
bool isValidShelfPlacement(int shelfCode, int occupiedMask) {
  int slots = shelfCode & 0xFF;
  int weightFlags = (shelfCode >> 8) & 0xFF;

  if (slots == 0) return false;
  if ((slots & occupiedMask) != 0) return false;

  int slotsCount = 0;
  int temp = slots;
  while (temp != 0) {
    slotsCount += temp & 1;
    temp >>= 1;
  }

  int flagsCount = 0;
  temp = weightFlags;
  while (temp != 0) {
    flagsCount += temp & 1;
    temp >>= 1;
  }

  if (slotsCount != flagsCount) return false;

  int lowest = slots & (-slots);
  int normalized = slots ~/ lowest;
  if ((normalized & (normalized + 1)) != 0) return false;

  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isValidShelfPlacement(0x0306, 0) == true);
  assert(isValidShelfPlacement(0x0305, 0) == false);
  assert(isValidShelfPlacement(0x0306, 0x02) == false);
  print('All tests passed!');
}

