int maxLedgerBalanceNoDoubleSkip(List<int> entries) {
  if (entries.isEmpty) return 0;
  int included = entries[0];
  int skipped = 0;
  for (int i = 1; i < entries.length; i++) {
    int prevIncluded = included;
    included = (included > skipped ? included : skipped) + entries[i];
    skipped = prevIncluded;
  }
  return included > skipped ? included : skipped;
