  final candidate = countBalancedMorseDecodings;

  expect(countBalancedMorseDecodings("", [".", "-"]), 1);
  expect(countBalancedMorseDecodings(".", [".", "-"]), 0);
  expect(countBalancedMorseDecodings(".-", [".", "-", ".-"]), 1);
  expect(countBalancedMorseDecodings(".-.-.-", [".", "-", ".-", "-."]), 3);
  expect(countBalancedMorseDecodings("---", ["-", "--", "---"]), 0);
  expect(countBalancedMorseDecodings("....", [".", ".."]), 0);
  expect(countBalancedMorseDecodings(".-.-", [".-"]), 0);
}

