@pragma('vm:entry-point')
int minSeatsToVacateForGroup(List<int> seats, int groupSize) {
  if (groupSize == 0) return 0;
  if (seats.length < groupSize) return -1;
  int currentOccupied = 0;
  for (int i = 0; i < groupSize; i++) {
    currentOccupied += seats[i];
  }
  int minOccupied = currentOccupied;
  for (int i = groupSize; i < seats.length; i++) {
    currentOccupied += seats[i] - seats[i - groupSize];
    if (currentOccupied < minOccupied) {
      minOccupied = currentOccupied;
    }
  }
  return minOccupied;
}

@pragma('vm:entry-point')
void main() {
  assert(minSeatsToVacateForGroup([1, 0, 1, 0], 2) == 1);
  assert(minSeatsToVacateForGroup([0, 0, 0], 2) == 0);
  assert(minSeatsToVacateForGroup([1, 1, 1], 2) == 2);
  print('All tests passed!');
}

