@pragma('vm:entry-point')
int findFirstContainedGreenPhase(List<int> phaseBoundaries, int rangeStart, int rangeEnd) {
  if (phaseBoundaries.length < 2) return -1;
  int low = 0;
  int high = (phaseBoundaries.length - 1) ~/ 3;
  int result = -1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    int startIdx = 3 * mid;
    int endIdx = 3 * mid + 1;
    if (endIdx >= phaseBoundaries.length) {
      high = mid - 1;
      continue;
    }
    int greenStart = phaseBoundaries[startIdx];
    int greenEnd = phaseBoundaries[endIdx];
    if (greenStart < rangeStart) {
      low = mid + 1;
    } else if (greenEnd > rangeEnd) {
      high = mid - 1;
    } else {
      result = mid;
      high = mid - 1;
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(findFirstContainedGreenPhase([0, 30, 35, 60, 90, 95, 120, 150, 155, 180], 50, 100) == 1);
  assert(findFirstContainedGreenPhase([0, 30, 35, 60], 0, 30) == 0);
  assert(findFirstContainedGreenPhase([], 0, 100) == -1);
