List<String> findNearbyLedgerEntries(List<int> xCoords, List<int> yCoords, int vaultX, int vaultY, int maxDistance) {
  List<String> results = [];
  int limit = xCoords.length < yCoords.length ? xCoords.length : yCoords.length;
  for (int i = 0; i < limit; i++) {
    int dist = (xCoords[i] - vaultX).abs() + (yCoords[i] - vaultY).abs();
    if (dist <= maxDistance) {
      results.add("${xCoords[i]},${yCoords[i]}:$dist");
    }
  }
