@pragma('vm:entry-point')
int maxStationVotes(List<List<int>> voters, List<List<int>> stations) {
  if (stations.isEmpty) return 0;
  final voteCounts = List.filled(stations.length, 0);
  for (final voter in voters) {
    int bestDist = 0x7FFFFFFF;
    int bestCap = -1;
    int bestIdx = -1;
    for (int i = 0; i < stations.length; i++) {
      final s = stations[i];
      int dist = (voter[0] - s[0]).abs() + (voter[1] - s[1]).abs();
      int cap = s[2];
      if (dist < bestDist) {
        bestDist = dist;
        bestCap = cap;
        bestIdx = i;
      } else if (dist == bestDist) {
        if (cap > bestCap) {
          bestCap = cap;
          bestIdx = i;
        } else if (cap == bestCap) {
          // keep smallest index (no change)
        }
      }
    }
    voteCounts[bestIdx]++;
  }
  int maxVotes = 0;
  for (int v in voteCounts) {
    if (v > maxVotes) maxVotes = v;
  }
  return maxVotes;
}

