@pragma('vm:entry-point')
String evaluateMoistureRegion(int gridData, int regionMask) {
  if (regionMask == 0) return "Untracked";

  int masked = gridData & regionMask;
  if (masked == 0) {
    return "Completely Dry";
  }
  if (masked == regionMask) {
    return "Fully Moist";
  }

  int count = 0;
  int temp = masked;
  while (temp != 0) {
    count += (temp & 1);
    temp >>>= 1;
  }

  return "Mixed: $count moist";
}

@pragma('vm:entry-point')
void main() {
  assert(evaluateMoistureRegion(10, 15) == 'Mixed: 2 moist');
  assert(evaluateMoistureRegion(0, 12) == 'Completely Dry');
