List<int> generateDailyPacketSizes(int startDay, int durationDays, List<int> weeklyPacketSizes) {
  List<int> dailySizes = [];
  for (int i = 0; i < durationDays; i++) {
    int currentDay = startDay + i;
    int size = weeklyPacketSizes[(currentDay - 1) % 7];
    if (currentDay % 7 == 0) {
