bool isGreenChannelSubsetOfRed(int rgb) {
  // Extract the 8-bit red and green channels from the 24-bit RGB integer.
  int red = (rgb >> 16) & 0xFF;
  int green = (rgb >> 8) & 0xFF;

  // A bitmask is a subset of another if (A & ~B) == 0.
  // We check if every set bit in green is also set in red.
  return (green & ~red) == 0;
}

