List<String> filterPacketGridRows(List<List<int>> packetGrid, int minSize) {
  final rows = <String>[];
  for (final row in packetGrid) {
    final accepted = <String>[];
    for (final size in row) {
      if (size >= minSize) {
        accepted.add(size.toString());
