@pragma('vm:entry-point')
String compressWifiBins(List<int> strengths, int tolerance) {
  String classify(int value) {
    if (value < 25) {
      return 'D';
    }
    if (value < 50) {
      return 'W';
    }
    if (value < 75) {
      return 'G';
    }
    return 'E';
  }

  String build(int start, int end) {
    int minValue = strengths[start];
    int maxValue = strengths[start];
    int sum = 0;

    for (int i = start; i < end; i++) {
      int value = strengths[i];
      sum += value;
      if (value < minValue) {
        minValue = value;
      }
      if (value > maxValue) {
        maxValue = value;
      }
    }

    if (maxValue - minValue <= tolerance || end - start == 1) {
      return classify(sum ~/ (end - start));
    }

    int mid = start + ((end - start) ~/ 2);
    String left = build(start, mid);
    String right = build(mid, end);

    if (left == right && left.length == 1) {
      return left;
    }

    return '($left|$right)';
  }

  if (strengths.isEmpty) {
    return 'empty';
  }

  return build(0, strengths.length);
}

@pragma('vm:entry-point')
void main() {
  assert(compressWifiBins([10, 12, 11], 5) == 'D');
  assert(compressWifiBins([10, 80], 10) == '(D|E)');
  assert(compressWifiBins([40, 45, 42, 44], 5) == 'W');
  print('All tests passed!');
}

