  expect(candidate([10, 80], 10), '(D|E)');
  expect(candidate([30, 32, 70, 72], 3), '(W|G)');
  expect(candidate([55, 57, 59, 61], 10), 'G');
  expect(candidate([15, 18, 65, 68, 85, 88, 90, 92], 4), '((D|G)|E)');
}

