@pragma('vm:entry-point')
List<int> tournamentAdvancerSequence(List<int> powers) {
  if (powers.length == 0) return [];
  if (powers.length == 1) return [powers[0]];
  int n = powers.length;
  bool isPowerOfTwo = (n & (n - 1)) == 0;
  if (!isPowerOfTwo) return powers;
  int mid = n ~/ 2;
  List<int> left = tournamentAdvancerSequence(powers.sublist(0, mid));
  List<int> right = tournamentAdvancerSequence(powers.sublist(mid));
  List<int> result = [];
  result.addAll(left);
  result.addAll(right);
  int leftChamp = left.last;
  int rightChamp = right.last;
  result.add(leftChamp > rightChamp ? leftChamp : rightChamp);
  return result;
}

