@pragma('vm:entry-point')
List<int> findLongestAlternatingQrSegment(List<int> modules, int maxFlips) {
  if (modules.isEmpty || maxFlips < 0) return [-1, -1];

  int bestStart = -1;
  int bestEnd = -1;
  int bestLen = 0;

  for (int startVal = 0; startVal <= 1; startVal++) {
    int left = 0;
    int flips = 0;
    for (int right = 0; right < modules.length; right++) {
      int expected = (right % 2 == 0) ? startVal : (1 - startVal);
      if (modules[right] != expected) flips++;

      while (flips > maxFlips) {
        int expectedLeft = (left % 2 == 0) ? startVal : (1 - startVal);
        if (modules[left] != expectedLeft) flips--;
        left++;
      }

      int currentLen = right - left + 1;
      if (currentLen > bestLen || (currentLen == bestLen && left < bestStart)) {
        bestLen = currentLen;
        bestStart = left;
        bestEnd = right;
      }
    }
  }

  return [bestStart, bestEnd];
}

@pragma('vm:entry-point')
void main() {
  assert(findLongestAlternatingQrSegment([1, 1, 1, 0, 0, 1, 0, 1, 1, 1], 2).toString() == '[1, 7]');
  assert(findLongestAlternatingQrSegment([1, 0, 1, 0, 1], 0).toString() == '[0, 4]');
