int cardDeckRleChecksum(String encoded) {
  int checksum = 0;
  for (int i = 0; i < encoded.length; i += 2) {
    int count = encoded.codeUnitAt(i) - 48;
    String card = encoded[i + 1];
    int cardValue;
    switch (card) {
      case 'A': cardValue = 1; break;
      case 'T': cardValue = 10; break;
      case 'J': cardValue = 11; break;
      case 'Q': cardValue = 12; break;
      case 'K': cardValue = 13; break;
      default: cardValue = card.codeUnitAt(0) - 48;
    }
    if (count % 2 == 1) {
      checksum += count * count * cardValue;
    } else {
      checksum += count * cardValue;
    }
  }
  return checksum;
}

