@pragma('vm:entry-point')
int computePassWindowChecksum(String encodedPasses, int shift) {
  int checksum = 0;
  int index = 0;
  const int a = 65;
  const int zero = 48;
  while (index < encodedPasses.length) {
    int encodedUnit = encodedPasses.codeUnitAt(index);
    int decodedOffset = (encodedUnit - a - shift) % 26;
    if (decodedOffset < 0) decodedOffset += 26;
    int decodedChar = a + decodedOffset;
    index += 1;
    int duration = 0;
    while (index < encodedPasses.length) {
      int digit = encodedPasses.codeUnitAt(index);
      if (digit < zero || digit > zero + 9) break;
      duration = duration * 10 + (digit - zero);
      index += 1;
    }
    if (duration == 0) continue;
    if (decodedChar == 86) {
      checksum += duration * 10;
    } else if (decodedChar == 88) {
      checksum -= duration * 2;
    } else {
      checksum += (decodedChar - 64) * duration;
    }
  }
  return checksum;
}

@pragma('vm:entry-point')
void main() {
  assert(computePassWindowChecksum("V2X3", 0) == 14);
  assert(computePassWindowChecksum("W2Y3", 1) == 14);
  assert(computePassWindowChecksum("", 5) == 0);
  print('All tests passed!');
}

