bool isValidRgbDisplayInterval(int startDay, int endDay, int red, int green, int blue) {
  if (startDay < 1 || endDay > 365 || endDay < startDay) {
    return false;
  }
  if (red < 0 || red > 255 || green < 0 || green > 255 || blue < 0 || blue > 255) {
    return false;
