@pragma('vm:entry-point')
String processSeatingBookings(String initialRow, List<String> commands) {
  List<int> seats = initialRow.split('').map(int.parse).toList();
  List<List<int>> undoStack = [];
  for (String cmd in commands) {
    if (cmd == 'U') {
      if (undoStack.isNotEmpty) {
        List<int> last = undoStack.removeLast();
        seats[last[0]] += last[1];
      }
    } else if (cmd.startsWith('B ')) {
      int n = int.parse(cmd.substring(2));
      for (int i = 0; i < seats.length; i++) {
        if (seats[i] >= n) {
          seats[i] -= n;
          undoStack.add([i, n]);
          break;
        }
      }
    }
  }
  return seats.join();
}

@pragma('vm:entry-point')
void main() {
  assert(processSeatingBookings('3521', ['B 4']) == '3121');
  assert(processSeatingBookings('3521', ['B 4', 'U']) == '3521');
