List<int> encodePacketSizes(List<int> packetSizes) {
  if (packetSizes.isEmpty) return [];
  List<int> result = [];
  int count = 1;
  int current = packetSizes[0];
  for (int i = 1; i < packetSizes.length; i++) {
    if (packetSizes[i] == current) {
      count++;
    } else {
      result.add(count);
      result.add(current);
      count = 1;
      current = packetSizes[i];
    }
  }
  result.add(count);
  result.add(current);
  return result;
}

