@pragma('vm:entry-point')
bool canReserveNonAdjacentSeats(List<bool> seats, int k) {
  int n = seats.length;
  List<int> dp = List.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    if (seats[i - 1]) {
      dp[i] = dp[i - 1];
    } else {
      int take = (i >= 2 ? dp[i - 2] : 0) + 1;
      int skip = dp[i - 1];
      dp[i] = take > skip ? take : skip;
    }
  }
  return dp[n] >= k;
}

