int thermostatSyncTime(List<int> cyclePeriods) {
  if (cyclePeriods.isEmpty) return 0;

  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  int lcm(int a, int b) {
    if (a == 0 || b == 0) return 0;
    return (a ~/ gcd(a, b)) * b;
  }

  int result = cyclePeriods[0];
  for (int i = 1; i < cyclePeriods.length; i++) {
    result = lcm(result, cyclePeriods[i]);
  }
  return result;
}

