@pragma('vm:entry-point')
int minimumShipmentCapacity(List<int> containerWeights, int k) {
  bool canShip(int capacity) {
    int shipments = 1;
    int currentLoad = 0;
    for (int w in containerWeights) {
      if (currentLoad + w > capacity) {
        shipments++;
        currentLoad = w;
        if (shipments > k) return false;
      } else {
        currentLoad += w;
      }
    }
    return true;
  }

  int low = containerWeights.reduce((a, b) => a > b ? a : b);
  int high = containerWeights.reduce((a, b) => a + b);
  while (low < high) {
    int mid = low + ((high - low) >> 1);
    if (canShip(mid)) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

@pragma('vm:entry-point')
