double averageTravelDistance(List<List<int>> requests) {
  int totalRequests = 0;
  int totalDistance = 0;
  for (int i = 0; i < requests.length; i++) {
    for (int j = 0; j < requests[i].length; j++) {
      int count = requests[i][j];
      totalRequests += count;
      totalDistance += count * (i - j).abs();
    }
  }
  if (totalRequests == 0) return 0.0;
  return totalDistance / totalRequests;
}

