@pragma('vm:entry-point')
List<String> getRemainingTrafficPhases(List<int> cumulativeEnds, List<String> phaseNames, int currentTime) {
  int left = 0;
  int right = cumulativeEnds.length - 1;
  int index = cumulativeEnds.length;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (cumulativeEnds[mid] > currentTime) {
      index = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  return phaseNames.sublist(index.clamp(0, phaseNames.length));
}

@pragma('vm:entry-point')
