String findMoistureThresholdIndex(List<double> readings, double threshold) {
  int lo = 0;
  int hi = readings.length;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (readings[mid] < threshold) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
