@pragma('vm:entry-point')
bool isSortedByKingDistance(List<String> squares, String from) {
  int kingDist(String sq) {
    int col = sq.codeUnitAt(0) - 'a'.codeUnitAt(0);
    int row = int.parse(sq[1]) - 1;
    int fromCol = from.codeUnitAt(0) - 'a'.codeUnitAt(0);
    int fromRow = int.parse(from[1]) - 1;
    int dc = (col - fromCol).abs();
    int dr = (row - fromRow).abs();
    return dc > dr ? dc : dr;
  }
  for (int i = 1; i < squares.length; i++) {
    if (kingDist(squares[i]) < kingDist(squares[i - 1])) return false;
  }
  return true;
}

