int countStationsInPassWindow(List<int> stationCoords, int satX, int satY, int windowRadius) {
  int count = 0;
  for (int i = 0; i < stationCoords.length; i += 2) {
    int dx = (stationCoords[i] - satX).abs();
    int dy = (stationCoords[i + 1] - satY).abs();
