List<String> parseDiceResults(String gameLog) {
  List<String> tokens = [];
  for (String round in gameLog.split('|')) {
    if (round.isEmpty) continue;
    int colonIdx = round.indexOf(':');
    if (colonIdx == -1) continue;
    String results = round.substring(colonIdx + 1);
