@pragma('vm:entry-point')
List<int> recursiveHashBucketTally(List<int> keys, int bucketCount) {
  if (keys.isEmpty) return List.filled(bucketCount, 0);
  if (keys.length == 1) {
    List<int> result = List.filled(bucketCount, 0);
    result[keys[0].abs() % bucketCount] = 1;
    return result;
  }
  int mid = keys.length ~/ 2;
  List<int> left = recursiveHashBucketTally(keys.sublist(0, mid), bucketCount);
  List<int> right = recursiveHashBucketTally(keys.sublist(mid), bucketCount);
  return [for (int i = 0; i < bucketCount; i++) left[i] + right[i]];
}

@pragma('vm:entry-point')
void main() {
  assert(recursiveHashBucketTally([1, 5, 9, 13], 4).toString() == '[0, 4, 0, 0]');
  assert(recursiveHashBucketTally([], 6).reduce((a, b) => a + b) == 0);
  assert(recursiveHashBucketTally([7], 5).toString() == '[0, 0, 1, 0, 0]');
