@pragma('vm:entry-point')
List<int> tallyVotesWithUndo(List<String> actions) {
  List<int> stack = [];
  int maxCand = -1;
  for (String action in actions) {
    if (action.startsWith('VOTE ')) {
      int cand = int.parse(action.substring(5));
      stack.add(cand);
      if (cand > maxCand) maxCand = cand;
    } else if (action == 'UNDO' && stack.isNotEmpty) {
      stack.removeLast();
    }
  }
  List<int> counts = List.filled(maxCand + 1, 0);
  for (int v in stack) {
    counts[v]++;
  }
  return counts;
}

@pragma('vm:entry-point')
void main() {
  assert(tallyVotesWithUndo(["VOTE 0", "VOTE 1", "VOTE 0"]).toString() == "[2, 1]");
  assert(tallyVotesWithUndo(["VOTE 0", "VOTE 1", "UNDO"]).toString() == "[1, 0]");
  assert(tallyVotesWithUndo([]).toString() == "[]");
  print('All tests passed!');
}

