bool isStrictlyRisingTideSequence(String readings) {
  if (readings.isEmpty) return false;
  List<String> tokens = readings.split(' ');
  double previous = -1.0;
  for (String token in tokens) {
    double height = double.parse(token);
    if (height <= previous) return false;
    previous = height;
