List<int> getBracketRanges(int numPlayers, int seed) {
  int rounds = 0;
  int temp = numPlayers;
  while (temp > 1) {
    temp >>= 1;
    rounds++;
  }
  List<int> result = [];
  for (int r = 1; r <= rounds; r++) {
    int bracketSize = 1 << r;
    int bracketIndex = (seed - 1) ~/ bracketSize;
    int minSeed = bracketIndex * bracketSize + 1;
    int maxSeed = minSeed + bracketSize - 1;
    result.add(minSeed);
    result.add(maxSeed);
  }
  return result;
}

@pragma('vm:entry-point')
