@pragma('vm:entry-point')
int countUsableSeatBlocks(int rowCount, int neededRows, List<int> bookingRows, List<int> bookingStartDays, List<int> bookingDurations) {
  if (neededRows > rowCount || neededRows <= 0) {
    return 0;
  }
  if (bookingRows.isEmpty) {
    return 0;
  }

  int lastDay = 0;
  for (int i = 0; i < bookingRows.length; i++) {
    int endDay = bookingStartDays[i] + bookingDurations[i] - 1;
    if (endDay > lastDay) {
      lastDay = endDay;
    }
  }

  int usableDays = 0;

  for (int day = 0; day <= lastDay; day++) {
    List<bool> occupied = List<bool>.filled(rowCount, false);

    for (int i = 0; i < bookingRows.length; i++) {
      int row = bookingRows[i];
      int start = bookingStartDays[i];
      int end = start + bookingDurations[i] - 1;

      if (row >= 0 && row < rowCount && day >= start && day <= end) {
        occupied[row] = true;
      }
    }

    int currentFree = 0;
    int bestFree = 0;

    for (int row = 0; row < rowCount; row++) {
      if (!occupied[row]) {
        currentFree++;
        if (currentFree > bestFree) {
          bestFree = currentFree;
        }
      } else {
        currentFree = 0;
      }
    }

    if (bestFree >= neededRows) {
      usableDays++;
    }
  }

  return usableDays;
}

