bool isTrafficLightBalanced(List<String> phases) {
  if (phases.isEmpty) return false;
  final validPhases = {'red', 'yellow', 'green'};
  final counts = <String, int>{};
  for (final phase in phases) {
    if (!validPhases.contains(phase)) return false;
    counts[phase] = (counts[phase] ?? 0) + 1;
  }
  if (counts.length != 3) return false;
  final values = counts.values.toList();
  final maxCount = values.reduce((a, b) => a > b ? a : b);
  final minCount = values.reduce((a, b) => a < b ? a : b);
  return maxCount - minCount <= 1;
}

