List<int> findFrequencyBalancedAccounts(List<String> ledger) {
  final accountCurrencyCount = <int, Map<String, int>>{};
  for (final entry in ledger) {
    final parts = entry.split(':');
    if (parts.length != 3) continue;
    final accountId = int.parse(parts[0]);
    final currency = parts[2];
    accountCurrencyCount.putIfAbsent(accountId, () => <String, int>{});
    final currencyCount = accountCurrencyCount[accountId]!;
    currencyCount[currency] = (currencyCount[currency] ?? 0) + 1;
  }
  final result = <int>[];
  for (final accountEntry in accountCurrencyCount.entries) {
    final frequencies = accountEntry.value.values;
    if (frequencies.length < 2) continue;
    final freqSet = frequencies.toSet();
    if (freqSet.length == 1) {
      result.add(accountEntry.key);
    }
  }
  result.sort();
  return result;
}

