@pragma('vm:entry-point')
int countPasswordCriteriaMet(String password, String policy) {
  int met = 0;
  for (final rule in policy.split(',')) {
    final parts = rule.split(':');
    if (parts.length != 2) continue;
    final min = int.tryParse(parts[1]);
    if (min == null || min < 0) continue;
    int count = 0;
    for (int i = 0; i < password.length; i++) {
      final c = password.codeUnitAt(i);
      switch (parts[0]) {
        case 'L': if (c >= 97 && c <= 122) count++; break;
        case 'U': if (c >= 65 && c <= 90) count++; break;
        case 'D': if (c >= 48 && c <= 57) count++; break;
        case 'S': if (c < 48 || (c > 57 && c < 65) || (c > 90 && c < 97) || c > 122) count++; break;
        case 'N': count++; break;
      }
    }
    if (count >= min) met++;
  }
  return met;
}

@pragma('vm:entry-point')
void main() {
  assert(countPasswordCriteriaMet("Hello1!", "L:1,U:1,D:1,S:1") == 4);
  assert(countPasswordCriteriaMet("abc", "L:1,U:1") == 1);
  assert(countPasswordCriteriaMet("", "N:0") == 1);
  print('All tests passed!');
}

