@pragma('vm:entry-point')
bool hasBarcodeSegmentSum(String barcode, int target) {
  if (barcode.isEmpty) return false;
  if (target == 0) return barcode.contains('0');
  List<int> digits = barcode.codeUnits.map((c) => c - 48).toList();
  int n = digits.length;
  int start = 0, end = 0, sum = digits[0];
  while (end < n) {
    if (sum == target) {
      return true;
    } else if (sum < target) {
      end++;
      if (end < n) sum += digits[end];
    } else {
      sum -= digits[start];
      start++;
      if (start > end && start < n) {
        end = start;
        sum = digits[start];
      }
    }
  }
  return false;
}

@pragma('vm:entry-point')
