@pragma('vm:entry-point')
bool securesMajorityThroughRecount(List<int> tallies, int threshold) {
  if (threshold <= 0) return true;
  if (tallies.isEmpty) return false;
  if (tallies.length == 1) {
    return tallies[0] >= threshold;
  }
  int mid = tallies.length ~/ 2;
  List<int> left = tallies.sublist(0, mid);
  List<int> right = tallies.sublist(mid);
  int leftSum = 0;
  for (int v in left) {
    leftSum += v;
  }
  int rightSum = 0;
  for (int v in right) {
    rightSum += v;
  }
  if (leftSum >= threshold || rightSum >= threshold) return true;
  return securesMajorityThroughRecount(left, threshold - rightSum) ||
         securesMajorityThroughRecount(right, threshold - leftSum);
}

@pragma('vm:entry-point')
void main() {
  assert(securesMajorityThroughRecount([3, 4, 5], 7) == true);
  assert(securesMajorityThroughRecount([1, 1], 3) == false);
  print('All tests passed!');
}

