List<String> encodeSpellCheckRuns(String word) {
  if (word.isEmpty) return [];
  List<String> result = [];
  int i = 0;
  while (i < word.length) {
    int j = i;
    while (j < word.length && word[j] == word[i]) {
      j++;
    }
    int count = j - i;
    if (count == 1) {
      result.add(word[i]);
    } else {
      result.add('${word[i]}:$count');
    }
    i = j;
  }
  return result;
}

