@pragma('vm:entry-point')
List<String> sortTrainTimetable(List<int> minutes) {
  var sorted = List<int>.from(minutes);
  sorted.sort((a, b) {
    int minuteA = a % 60;
    int minuteB = b % 60;
    if (minuteA != minuteB) return minuteA.compareTo(minuteB);
    return (a ~/ 60).compareTo(b ~/ 60);
  });
  return sorted.map((m) {
    int h = m ~/ 60;
    int min = m % 60;
    return '${h.toString().padLeft(2, '0')}:${min.toString().padLeft(2, '0')}';;
  }).toList();
}

