@pragma('vm:entry-point')
List<int> busyPacketBuckets(List<int> sizes, int bucketWidth, int minCount) {
  // Group packet sizes into buckets of width bucketWidth (bucket start = index * bucketWidth),
  // count packets per bucket, and return the bucket start values for buckets whose
  // packet count is at least minCount, ordered by count descending, ties by start ascending.
  final Map<int, int> counts = {};
  for (final size in sizes) {
    final bucket = size ~/ bucketWidth;
    counts[bucket] = (counts[bucket] ?? 0) + 1;
  }
  final List<int> qualifying = [];
  counts.forEach((bucket, count) {
    if (count >= minCount) {
      qualifying.add(bucket);
    }
  });
  qualifying.sort((a, b) {
    final diff = counts[b]! - counts[a]!;
    if (diff != 0) {
      return diff;
    }
    return a - b;
  });
  return qualifying.map((bucket) => bucket * bucketWidth).toList();
}

@pragma('vm:entry-point')
void main() {
  assert(busyPacketBuckets([64, 70, 128, 130, 1500, 65], 100, 2).toString() == '[0, 100]');
  assert(busyPacketBuckets([], 100, 1).isEmpty);
  assert(busyPacketBuckets([512], 100, 1).first == 500);
