@pragma('vm:entry-point')
int longestMorseAlternation(int encodedMorse) {
  if (encodedMorse < 0) return 0;

  int length = (encodedMorse >> 27) & 0x1F;
  if (length <= 0 || length > 31) return 0;

  int mask = (1 << length) - 1;
  int symbols = encodedMorse & mask;

  int matchA = (~(symbols ^ 0x55555555)) & mask;
  int matchB = (~(symbols ^ 0xAAAAAAAA)) & mask;

  int maxRunA = 0;
  int tempA = matchA;
  while (tempA != 0) {
    tempA &= (tempA << 1);
    maxRunA++;
  }

  int maxRunB = 0;
  int tempB = matchB;
  while (tempB != 0) {
    tempB &= (tempB << 1);
    maxRunB++;
  }

  return maxRunA > maxRunB ? maxRunA : maxRunB;
}

@pragma('vm:entry-point')
void main() {
  assert(longestMorseAlternation((5 << 27) | 10) == 5);
  assert(longestMorseAlternation((4 << 27) | 0) == 1);
  assert(longestMorseAlternation((3 << 27) | 13) == 3);
  print('All tests passed!');
}

