@pragma('vm:entry-point')
int maxTideSubarraySumWithSingleDrop(List<int> tides, int minSafe) {
  if (tides.isEmpty) return 0;
  const int negInf = -1000000000;
  int dp0 = negInf, dp1 = negInf, maxSum = negInf;
  for (int t in tides) {
    int n0 = negInf, n1 = negInf;
    if (t >= minSafe) {
      n0 = dp0 == negInf ? t : (t > dp0 + t ? t : dp0 + t);
      n1 = dp0;
      if (dp1 != negInf) n1 = n1 > dp1 + t ? n1 : dp1 + t;
    } else {
      n1 = dp0;
    }
    dp0 = n0;
    dp1 = n1;
    if (dp0 > maxSum) maxSum = dp0;
    if (dp1 > maxSum) maxSum = dp1;
  }
  return maxSum == negInf ? 0 : maxSum;
}

