@pragma('vm:entry-point')
int countUrgentRestockSlots(
    List<int> stocks,
    List<int> dailyDemands,
    List<int> supplierLeadTimes,
    List<bool> isFrozen,
    int priorityThreshold) {
  int n = stocks.length;
  // Build the candidate index list, dropping frozen SKUs entirely.
  List<int> candidates = <int>[];
  for (int i = 0; i < n; i++) {
    if (!isFrozen[i]) {
      candidates.add(i);
    }
  }
  // Sort by priority score (demand*leadTime - stock) descending,
  // tiebroken by higher daily demand first.
  candidates.sort((a, b) {
    int scoreA = dailyDemands[a] * supplierLeadTimes[a] - stocks[a];
    int scoreB = dailyDemands[b] * supplierLeadTimes[b] - stocks[b];
    if (scoreA != scoreB) return scoreB.compareTo(scoreA);
    return dailyDemands[b].compareTo(dailyDemands[a]);
  });
  // Count items meeting the threshold; list is sorted, so stop at first miss.
  int count = 0;
  for (int i = 0; i < candidates.length; i++) {
    int idx = candidates[i];
    int score = dailyDemands[idx] * supplierLeadTimes[idx] - stocks[idx];
    if (score >= priorityThreshold) {
      count++;
    } else {
      break;
    }
  }
  return count;
}

@pragma('vm:entry-point')
void main() {
  assert(countUrgentRestockSlots([10, 50, 20], [5, 2, 3], [3, 4, 2], [false, false, false], 0) == 1);
  assert(countUrgentRestockSlots([], [], [], [], 0) == 0);
  assert(countUrgentRestockSlots([0, 0, 0], [5, 5, 5], [3, 3, 3], [false, false, false], 10) == 3);
  print('All tests passed!');
}

