String sortDiceRoundsByParityAndValue(List<int> rounds) {
  List<int> sorted = List<int>.from(rounds);
  sorted.sort((int a, int b) {
    int parityA = a % 2 == 0 ? 0 : 1;
    int parityB = b % 2 == 0 ? 0 : 1;
    if (parityA != parityB) {
      return parityA - parityB;
    }
    return b - a;
  });
  return sorted.join(' ');
}

