@pragma('vm:entry-point')
bool hasBatteryReachedTargetCycle(List<int> cycleCharges, int targetCharge) {
  int left = 0;
  int right = cycleCharges.length - 1;

  while (left <= right) {
    int mid = (left + right) ~/ 2;

    if (cycleCharges[mid] == targetCharge) {
      return true;
    }

    if (cycleCharges[mid] < targetCharge) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return false;
}

