List<String> findCentRoundingDistributions(int totalCents, int shareCount) {
  if (totalCents < 0 || shareCount <= 0) return [];
  int base = totalCents ~/ shareCount, rem = totalCents % shareCount;
  List<String> results = [];
  void distribute(int idx, int left, String prefix) {
    if (idx == shareCount) {
      if (left == 0) results.add(prefix);
      return;
    }
    String sep = idx > 0 ? ", " : "";
    if (left > 0) distribute(idx + 1, left - 1, "$prefix${sep}Share${idx + 1}:${base + 1}¢");
    distribute(idx + 1, left, "$prefix${sep}Share${idx + 1}:$base¢");
  }
  distribute(0, rem, "");
  return results;
}

