int batteryIdWithMostDeepDischargeCycles(List<int> batteryIds, List<int> dischargeDepths) {
  if (batteryIds.length != dischargeDepths.length) {
    throw ArgumentError('batteryIds and dischargeDepths must have the same length');
  }

  final deepCycleCounts = <int, int>{};

  for (var i = 0; i < batteryIds.length; i++) {
    if (dischargeDepths[i] > 80) {
      final id = batteryIds[i];
      deepCycleCounts[id] = (deepCycleCounts[id] ?? 0) + 1;
    }
  }

  if (deepCycleCounts.isEmpty) {
    return -1;
  }

  var winningId = -1;
  var maxCount = -1;

  for (final entry in deepCycleCounts.entries) {
    final id = entry.key;
    final count = entry.value;
    if (count > maxCount || (count == maxCount && id < winningId)) {
      maxCount = count;
      winningId = id;
    }
  }

  return winningId;
}

