String compressDeckMarks(String deckMarks) {
  if (deckMarks.isEmpty) {
    return '';
  }
  String result = '';
  int count = 1;
  for (int i = 1; i <= deckMarks.length; i++) {
    if (i < deckMarks.length && deckMarks[i] == deckMarks[i - 1]) {
      count++;
    } else {
      result += deckMarks[i - 1] + count.toString();
