@pragma('vm:entry-point')
int finalTideHeight(List<String> events) {
  int height = 0;
  List<int> history = [];

  for (String event in events) {
    List<String> parts = event.split(' ');

    if (parts[0] == 'high') {
      int amount = int.parse(parts[1]);
      height += amount;
      history.add(amount);
    } else if (parts[0] == 'low') {
      int amount = int.parse(parts[1]);
      height -= amount;
      history.add(-amount);
    } else if (parts[0] == 'repeat') {
      if (history.isNotEmpty) {
        int last = history.last;
        height += last;
        history.add(last);
      }
    } else if (parts[0] == 'cancel') {
      int count = int.parse(parts[1]);

      for (int i = 0; i < count; i++) {
        if (history.isNotEmpty) {
          int removed = history.removeLast();
          height -= removed;
        }
      }
    }
  }

  return height;
}

@pragma('vm:entry-point')
void main() {
  assert(finalTideHeight(['high 4', 'low 1', 'repeat']) == 2);
  assert(finalTideHeight(['high 7', 'repeat', 'cancel 1']) == 7);
  assert(finalTideHeight(['low 3', 'high 10', 'cancel 2']) == 0);
  print('All tests passed!');
}

