@pragma('vm:entry-point')
List<String> getUpbeatSongs(List<String> songs, List<int> bpms, int targetBpm, int maxCount) {
  if (songs.isEmpty || maxCount <= 0) return [];
  int left = 0, right = bpms.length;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (bpms[mid] < targetBpm) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  int end = left + maxCount;
  if (end > songs.length) end = songs.length;
  return songs.sublist(left, end);
}

