double computeBundledInventoryValue(List<double> itemValues) {
  if (itemValues.isEmpty) {
    return 0.0;
  }
  if (itemValues.length == 1) {
    return itemValues[0];
  }
  itemValues = List<double>.from(itemValues);
  itemValues.sort();
  int mid = itemValues.length ~/ 2;
  List<double> left = itemValues.sublist(0, mid);
  List<double> right = itemValues.sublist(mid);
  double leftVal = computeBundledInventoryValue(left);
  double rightVal = computeBundledInventoryValue(right);
  double combined = leftVal + rightVal;
  if (combined > 10.0) {
    combined = combined * 0.75;
  }
  return combined / 2.0;
}

