List<int> trafficLightPhases(int startDay, int numDays, int greenDays, int yellowDays, int redDays) {
  int cycleLength = greenDays + yellowDays + redDays;
  List<int> phases = [];
  for (int i = 0; i < numDays; i++) {
    int dayInCycle = (startDay + i) % cycleLength;
    if (dayInCycle < greenDays) {
      phases.add(0);
    } else if (dayInCycle < greenDays + yellowDays) {
      phases.add(1);
    } else {
      phases.add(2);
    }
  }
  return phases;
}

