List<String> manhattanDistanceGrid(int centerX, int centerY, int radius) {
  List<String> rows = [];
  for (int y = centerY + radius; y >= centerY - radius; y--) {
    StringBuffer sb = StringBuffer();
    for (int x = centerX - radius; x <= centerX + radius; x++) {
      int d = (x - centerX).abs() + (y - centerY).abs();
      if (x > centerX - radius) sb.write(' ');
      sb.write(d);
    }
    rows.add(sb.toString());
  }
  return rows;
}

