@pragma('vm:entry-point')
String findScheduledTemperature(List<int> setpoints, int targetTemp) {
  if (setpoints.isEmpty) return "No schedule";
  int low = 0;
  int high = setpoints.length - 1;
  int result = -1;
  while (low <= high) {
    int mid = (low + high) ~/ 2;
    if (setpoints[mid] <= targetTemp) {
      result = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  if (result == -1) {
    return "Below minimum: ${setpoints[0]}°C";
  }
  return "Set to ${setpoints[result]}°C";
}

@pragma('vm:entry-point')
void main() {
  assert(findScheduledTemperature([16, 18, 20, 22, 24], 21) == "Set to 20°C");
  assert(findScheduledTemperature([16, 18, 20, 22, 24], 15) == "Below minimum: 16°C");
  assert(findScheduledTemperature([], 20) == "No schedule");
  print('All tests passed!');
}

