@pragma('vm:entry-point')
bool isStructuredServerLog(String line) {
  int state = 0;
  int digits = 0;
  for (int i = 0; i < line.length; i++) {
    String c = line[i];
    if (state == 0) {
      if (c == '|') state = 1;
    } else if (state == 1) {
      if (c.codeUnitAt(0) >= 48 && c.codeUnitAt(0) <= 57) {
        digits++;
      } else if (c == '|' && digits == 3) {
        state = 2;
      } else {
        return false;
      }
    } else if (c == '|') {
      return false;
    }
  }
  int first = line.indexOf('|');
  String level = first == -1 ? "" : line.substring(0, first);
  return (level == 'INFO' || level == 'WARN' || level == 'ERROR') && state == 2 && line.lastIndexOf('|') < line.length - 1;
}

@pragma('vm:entry-point')
void main() {
  assert(isStructuredServerLog('INFO|200|started') == true);
  assert(isStructuredServerLog('WARN|12|short') == false);
  assert(isStructuredServerLog('DEBUG|404|missing') == false);
