@pragma('vm:entry-point')
int calculateUniqueMorseDuration(List<String> signals) {
  return signals
      .toSet()
      .where((s) => s.isNotEmpty && s.split('').every((c) => c == '.' || c == '-'))
      .fold(0, (sum, s) {
    int dots = s.split('').where((c) => c == '.').length;
    int dashes = s.length - dots;
    return sum + dots + (dashes * 3);
  });
}

