int countSuggestionEditPositions(List<List<String>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0;
  final rows = grid.length;
  final cols = grid[0].length;
  var edits = 0;
  for (var c = 0; c < cols; c++) {
    final target = grid[0][c];
    var ok = true;
    for (var r = 1; r < rows; r++) {
      if (grid[r][c] != target) { ok = false; break; }
    }
    if (!ok) edits++;
  }
  return edits;
}

