@pragma('vm:entry-point')
String computeBucketCounts(String text, int numBuckets) {
  if (numBuckets <= 0) return "";
  final counts = List<int>.filled(numBuckets, 0);
  final tokens = text.trim().split(RegExp(r'\s+'));
  for (final token in tokens) {
    if (token.isEmpty) continue;
    int hash = 0;
    for (int i = 0; i < token.length; i++) {
      hash = (hash + token.codeUnitAt(i)) % numBuckets;
    }
    counts[hash]++;
  }
  final result = <String>[];
  for (int i = 0; i < numBuckets; i++) {
    if (counts[i] > 0) {
      result.add('$i:${counts[i]}');
    }
  }
  return result.join(',');
}

@pragma('vm:entry-point')
void main() {
  assert(computeBucketCounts("a b c", 5) == "2:1,3:1,4:1");
  assert(computeBucketCounts("", 3) == "");
  assert(computeBucketCounts("x x x", 4) == "0:3");
  print('All tests passed!');
}

