@pragma('vm:entry-point')
int countMorsePartitions(String signal) {
  int n = signal.length;
  if (n == 0) return 0;
  // dp[i] = number of valid partitions of signal[0..i-1]
  // A valid segment has length 2..5 and its first and last symbols differ.
  List<int> dp = List.filled(n + 1, 0);
  dp[0] = 1;
  for (int i = 1; i <= n; i++) {
    for (int len = 2; len <= 5; len++) {
      int start = i - len;
      if (start < 0) break;
      if (dp[start] == 0) continue;
      if (signal[start] != signal[i - 1]) {
        dp[i] += dp[start];
      }
    }
  }
  return dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(countMorsePartitions(".-") == 1);
  assert(countMorsePartitions(".-.-") == 2);
  assert(countMorsePartitions(".-.-.-") == 3);
  print('All tests passed!');
}

