List<int> mostFrequentCharCodePerRow(List<String> rows) {
  List<int> result = [];
  for (String row in rows) {
    if (row.isEmpty) {
      result.add(0);
      continue;
    }
    Map<int, int> freq = {};
    for (int i = 0; i < row.length; i++) {
      int code = row.codeUnitAt(i);
      freq[code] = (freq[code] ?? 0) + 1;
    }
    int bestCode = 0;
    int bestCount = 0;
    freq.forEach((code, count) {
      if (count > bestCount || (count == bestCount && code < bestCode)) {
        bestCount = count;
        bestCode = code;
      }
    });
    result.add(bestCode);
  }
  return result;
}

