@pragma('vm:entry-point')
int parsePacketSizeSpec(String spec) {
  int total = 0;
  int current = 0;
  int state = 0; // 0=start/after+, 1=in digits, 2=after suffix
  for (int i = 0; i < spec.length; i++) {
    int code = spec.codeUnitAt(i);
    if (code >= 48 && code <= 57) {
      if (state == 0 || state == 1) {
        current = current * 10 + (code - 48);
        state = 1;
      }
    } else if (code == 75) { // 'K'
      if (state == 1) {
        current *= 1024;
        total += current;
        current = 0;
        state = 2;
      }
    } else if (code == 77) { // 'M'
      if (state == 1) {
        current *= 1048576;
        total += current;
        current = 0;
        state = 2;
      }
    } else if (code == 43) { // '+'
      if (state == 1) {
        total += current;
        current = 0;
      }
      state = 0;
    }
  }
  if (state == 1) {
    total += current;
  }
  return total;
}

