@pragma('vm:entry-point')
int calculateSoilMoisture(String grid) {
  if (grid.isEmpty) return 0;
  final cellPattern = RegExp(r'^([WDM])(\d)$');
  int total = 0;
  final rows = grid.split('|');
  for (final row in rows) {
    if (row.isEmpty) continue;
    final cells = row.split(',');
    int rowSum = 0;
    bool valid = true;
    for (final cell in cells) {
      final m = cellPattern.firstMatch(cell);
      if (m == null) {
        valid = false;
        break;
      }
      final type = m.group(1)!;
      final digit = int.parse(m.group(2)!);
      if (type == 'W') {
        rowSum += digit * 2;
      } else if (type == 'M') {
        rowSum += digit * 3;
      } else {
        rowSum -= digit;
      }
    }
    if (valid) total += rowSum;
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateSoilMoisture('W3,D1,M2|M4,D0|W2') == 27);
  assert(calculateSoilMoisture('W5,D2,M1') == 11);
  assert(calculateSoilMoisture('') == 0);
  print('All tests passed!');
}

