@pragma('vm:entry-point')
String decodeShelfCode(int code) {
  // A 16-bit shelf code: bits 0-7 = shelf id, bits 8-11 = status flags,
  // bits 12-15 = checksum nibble that must equal the popcount of bits 0-11.
  int low = code & 0xFFF;
  int check = (code >> 12) & 0xF;
  int pop = 0;
  for (int i = 0; i < 12; i++) {
    if (((low >> i) & 1) == 1) {
      pop++;
    }
  }
  if (pop != check) {
    return 'INVALID';
  }
  int id = code & 0xFF;
  List<String> flags = [];
  if (((code >> 8) & 1) == 1) flags.add('RESERVED');
  if (((code >> 9) & 1) == 1) flags.add('FRAGILE');
  if (((code >> 10) & 1) == 1) flags.add('OVERSIZE');
  if (((code >> 11) & 1) == 1) flags.add('ARCHIVED');
  String flagPart = flags.isEmpty ? 'NONE' : flags.join('+');
  return 'S$id:$flagPart';
}

@pragma('vm:entry-point')
void main() {
  assert(decodeShelfCode(8197) == 'S5:NONE');
  assert(decodeShelfCode(12549) == 'S5:RESERVED');
  assert(decodeShelfCode(5) == 'INVALID');
  print('All tests passed!');
}

