  expect(candidate(53247), 'S255:RESERVED+FRAGILE+OVERSIZE+ARCHIVED');
  expect(candidate(18954), 'S10:FRAGILE+ARCHIVED');
  expect(candidate(9217), 'S1:OVERSIZE');
  expect(candidate(20741), 'INVALID');
  expect(candidate(33023), 'S255:NONE');
  expect(candidate(5), 'INVALID');
}

