@pragma('vm:entry-point')
List<int> deriveFragmentSizes(int totalBytes, int mtu) {
  if (totalBytes <= 0 || mtu <= 0) return [];
  if (totalBytes <= mtu) return [totalBytes];
  List<int> fragments = [];
  int remaining = totalBytes;
  int packet = mtu;
  while (remaining > 0) {
    if (packet > remaining) {
      packet = remaining;
    }
    int g = packet;
    int t = remaining;
    while (t != 0) {
      int tmp = t;
      t = g % t;
      g = tmp;
    }
    if (g > 1) {
      packet = (packet ~/ g) * g;
      if (packet == 0) packet = g;
    }
    if (packet > remaining) packet = remaining;
    fragments.add(packet);
    remaining -= packet;
    if (remaining > 0 && packet > mtu ~/ 2) {
      packet = mtu;
    }
  }
  return fragments;
}

@pragma('vm:entry-point')
void main() {
  assert(deriveFragmentSizes(100, 40).toString() == '[40, 40, 20]');
  assert(deriveFragmentSizes(17, 5).toString() == '[5, 5, 5, 2]');
