List<int> boardPositionGcds(int n) {
  List<int> result = [];
  for (int row = 0; row < n; row++) {
    for (int col = 0; col < n; col++) {
      int a = row + 1;
      int b = col + 1;
      while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
