@pragma('vm:entry-point')
String sortScheduleByPriority(List<Map<String, num>> entries) {
  if (entries.isEmpty) return "EMPTY";
  const double baseline = 68.0;
  List<Map<String, num>> sorted = List.from(entries);
  sorted.sort((a, b) {
    double devA = ((a["temp"] as double) - baseline).abs();
    double devB = ((b["temp"] as double) - baseline).abs();
    int cmp = devB.compareTo(devA);
    if (cmp != 0) return cmp;
    cmp = (a["start"] as int).compareTo(b["start"] as int);
    if (cmp != 0) return cmp;
    return (a["temp"] as double).compareTo(b["temp"] as double);
  });
  String fmt(Map<String, num> e) {
    int s = e["start"] as int;
    double t = e["temp"] as double;
    return "${(s ~/ 60).toString().padLeft(2, '0')}:${(s % 60).toString().padLeft(2, '0')}/$t";
  }
  return sorted.map(fmt).join("|");
}

@pragma('vm:entry-point')
void main() {
  assert(sortScheduleByPriority([]) == "EMPTY");
  assert(sortScheduleByPriority([{"start": 480, "temp": 72.0}]) == "08:00/72.0");
  assert(sortScheduleByPriority([{"start": 480, "temp": 72.0}, {"start": 360, "temp": 62.0}]) == "06:00/62.0|08:00/72.0");
  print('All tests passed!');
}

