List<int> scanQrModules(List<int> modules) {
  if (modules.isEmpty) return [];
  List<int> runs = [];
  int current = modules[0];
  int count = 1;
  for (int i = 1; i < modules.length; i++) {
    if (modules[i] == current) {
      count++;
    } else {
      runs.add(count);
      current = modules[i];
      count = 1;
    }
  }
  runs.add(count);
  return runs;
}

