bool isValidStarPattern(List<String> rows) {
  int totalStars = 0;
  for (String row in rows) {
    int count = 0;
    for (int i = 0; i < row.length; i++) {
      if (row[i] == '*') {
        count++;
      }
    }
    if (count > 0) {
      if (count < 2) return false;
      for (int j = 2; j * j <= count; j++) {
        if (count % j == 0) return false;
      }
      totalStars += count;
    }
  }
  return totalStars > 0 && totalStars % 2 != 0;
}

