@pragma('vm:entry-point')
int calculateTotalSensorCoverage(List<int> starts, List<int> durations) {
  if (starts.isEmpty || durations.isEmpty || starts.length != durations.length) return 0;
  List<List<int>> intervals = [];
  for (int i = 0; i < starts.length; i++) {
    int s = starts[i];
    int d = durations[i];
    if (d <= 0 || s < 0) continue;
    intervals.add([s, s + d - 1]);
  }
  if (intervals.isEmpty) return 0;
  intervals.sort((a, b) => a[0].compareTo(b[0]));
  List<List<int>> merged = [];
  List<int> current = intervals[0];
  for (int i = 1; i < intervals.length; i++) {
    List<int> next = intervals[i];
    if (next[0] <= current[1] + 1) {
      if (next[1] > current[1]) current[1] = next[1];
    } else {
      merged.add(current);
      current = next;
    }
  }
  merged.add(current);
  int total = 0;
  for (List<int> iv in merged) {
    total += iv[1] - iv[0] + 1;
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(calculateTotalSensorCoverage([1, 5], [3, 2]) == 6);
  assert(calculateTotalSensorCoverage([], []) == 0);
