@pragma('vm:entry-point')
int longestProfitableAuditWindow(List<int> entries, int maxWithdrawals, int minNetChange) {
  int left = 0;
  int withdrawalCount = 0;
  int windowSum = 0;
  int bestLength = 0;

  for (int right = 0; right < entries.length; right++) {
    windowSum += entries[right];

    if (entries[right] < 0) {
      withdrawalCount++;
    }

    while (withdrawalCount > maxWithdrawals && left <= right) {
      windowSum -= entries[left];

      if (entries[left] < 0) {
        withdrawalCount--;
      }

      left++;
    }

    if (windowSum >= minNetChange) {
      int currentLength = right - left + 1;
      if (currentLength > bestLength) {
        bestLength = currentLength;
      }
    }
  }

  return bestLength;
}

@pragma('vm:entry-point')
