List<String> countIntervalDaysInBuckets(int startDay, int days, int buckets) {
  if (buckets <= 0 || days <= 0) return [];
  List<int> counts = List.filled(buckets, 0);
  for (int i = 0; i < days; i++) {
    int day = startDay + i;
    int bucket = day % buckets;
    if (bucket < 0) bucket += buckets;
    counts[bucket]++;
  }
  List<String> result = [];
  for (int b = 0; b < buckets; b++) {
    result.add('bucket$b:${counts[b]}');
  }
  return result;
}

