int libraryShelfCodeScore(String code) {
  int total = 0;
  int multiplier = 1;
  List<int> stack = [];
  for (int i = 0; i < code.length; i++) {
    String ch = code[i];
    if (ch == '(') {
      stack.add(multiplier);
      multiplier *= 2;
    } else if (ch == '[') {
      stack.add(multiplier);
      multiplier *= 3;
    } else if (ch == ')' || ch == ']') {
      if (stack.isNotEmpty) {
        multiplier = stack.removeLast();
      }
    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      int digit = ch.codeUnitAt(0) - 48;
      total += digit * multiplier;
    }
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(libraryShelfCodeScore("") == 0);
  assert(libraryShelfCodeScore("123") == 6);
  assert(libraryShelfCodeScore("([4])") == 24);
