@pragma('vm:entry-point')
int computePacketOverlapTotal(List<int> xs, List<int> ys, List<int> sizes) {
  int n = xs.length;
  int total = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      int x1 = xs[i];
      int y1 = ys[i];
      int s1 = sizes[i];
      int x2 = xs[j];
      int y2 = ys[j];
      int s2 = sizes[j];
      int left = x1 > x2 ? x1 : x2;
      int right = (x1 + s1 < x2 + s2) ? x1 + s1 : x2 + s2;
      int bottom = y1 > y2 ? y1 : y2;
      int top = (y1 + s1 < y2 + s2) ? y1 + s1 : y2 + s2;
      int overlapW = right - left;
      int overlapH = top - bottom;
      if (overlapW > 0 && overlapH > 0) {
        total += overlapW * overlapH;
      }
    }
  }
  return total;
}

@pragma('vm:entry-point')
void main() {
  assert(computePacketOverlapTotal([0, 3], [0, 0], [5, 4]) == 8);
  assert(computePacketOverlapTotal([], [], []) == 0);
  print('All tests passed!');
}

tests:
