List<String> soilMoistureStressFlags(List<int> moisture, int low, int high) {
  List<String> result = [];
  int stress = 0;
  for (int i = 0; i < moisture.length; i++) {
    int v = moisture[i];
    if (v < low) {
      stress += low - v;
    } else if (v > high) {
      stress += v - high;
    } else if (stress > 0) {
      stress -= 1;
    }
    if (stress < 0) stress = 0;
    result.add(stress == 0 ? "stable" : "stress=$stress");
  }
  return result;
}

