@pragma('vm:entry-point')
List<int> discoverBalancedShelfArrangement(List<int> shelfCodes) {
  List<int> best = [];
  void backtrack(int idx, int sum, List<int> path) {
    if (idx == shelfCodes.length) {
      if (sum == 0) {
        if (best.isEmpty || path.join('').compareTo(best.join('')) < 0) {
          best = List.from(path);
        }
      }
      return;
    }
    path.add(1);
    backtrack(idx + 1, sum + shelfCodes[idx], path);
    path.removeLast();
    path.add(-1);
    backtrack(idx + 1, sum - shelfCodes[idx], path);
    path.removeLast();
  }
  backtrack(0, 0, []);
  return best;
}

@pragma('vm:entry-point')
void main() {
  assert(discoverBalancedShelfArrangement([1, 2, 3]).toString() == '[1, 1, -1]');
  assert(discoverBalancedShelfArrangement([]).toString() == '[]');
  print('All tests passed!');
}

