List<int> getValidPasswordAccessDays(int issueDay, int validDuration, List<int> accessLog) {
  List<int> validDays = [];
  int endDay = issueDay + validDuration;
  for (int day in accessLog) {
    if (day > issueDay && day < endDay) {
      int weekDay = day % 7;
      if (weekDay != 5 && weekDay != 6) {
        validDays.add(day);
      }
    }
  }
  return validDays;
}

